internal val PACK_RU_HANDBOOK: Map<String, String> = mapOf(

    // ---------- h1 ----------
    "hb.h1.s1.h" to "AMS (острая горная болезнь)",
    "hb.h1.s1.b" to "Критерии Lake Louise: головная боль после недавнего набора высоты плюс хотя бы один из признаков — тошнота или рвота, головокружение, усталость, нарушение сна. Симптомы обычно появляются через 6–12 часов после прибытия на высоту. Риск растёт с высотой: ниже 2 500 м болезнь редка, а на 2 500–4 300 м поражает примерно 25–43 % людей.",
    "hb.h1.s2.h" to "HACE (высотный отёк головного мозга)",
    "hb.h1.s2.b" to "Ключевые признаки — атаксия и нарушение сознания: неспособность идти по прямой пятка к носку, неустойчивая походка, сонливость, неадекватное поведение, галлюцинации. Это неотложное состояние, которое может убить за несколько часов. Немедленно спускайтесь и вызывайте медицинскую помощь.",
    "hb.h1.s3.h" to "HAPE (высотный отёк лёгких)",
    "hb.h1.s3.b" to "Типичные признаки: одышка в покое, резкое падение работоспособности, сухой кашель, переходящий во влажный с пенистой мокротой, синюшные губы. HAPE — ведущая причина смерти от высотной патологии и может развиваться очень быстро.",
    "hb.h1.s4.h" to "Тактика и золотые правила",
    "hb.h1.s4.b" to "Первое: на высоте любое недомогание считайте высотной болезнью, пока не доказано обратное. Второе: никогда не поднимайтесь с симптомами. Третье: при ухудшении немедленно спускайтесь. Четвёртое: в тяжёлых случаях спускайтесь и сразу обращайтесь за медицинской помощью. Спуск — единственное вмешательство, которое надёжно обращает болезнь; кислород, гипербарическая камера и лекарства лишь выигрывают время. Препараты (например, дексаметазон 4 мг каждые 6 часов у взрослых, либо нифедипин или ингибитор ФДЭ при HAPE) применяются по назначению врача.",
    // ---------- h2 ----------
    "hb.h2.s1.h" to "Два жёстких правила скорости подъёма",
    "hb.h2.s1.b" to "Первое: стартуя с малой высоты, не ночуйте выше 2 750 м в течение одних суток. Второе: выше 3 000 м ограничивайте суточный прирост высоты ночёвки 500 м или меньше и делайте день отдыха примерно каждые 1 000 м.",
    "hb.h2.s2.h" to "Поднимайся высоко, спи низко",
    "hb.h2.s2.b" to "Днём поднимайтесь и тренируйтесь выше, а ночевать возвращайтесь ниже. Такое сочетание сохраняет гипоксический стимул и защищает качество сна, а сон — ключевая переменная эффективной акклиматизации.",
    "hb.h2.s3.h" to "Профилактические препараты",
    "hb.h2.s3.b" to "Обычный профилактический препарат — ацетазоламид, его начинают за день до подъёма, по 125 мг два раза в день у взрослых. Начало в день подъёма тоже даёт некоторый эффект. Нужен рецепт: противопоказания и побочные эффекты оценивает врач.",
    "hb.h2.s4.h" to "Нелекарственные меры",
    "hb.h2.s4.b" to "Пейте достаточно, ешьте преимущественно углеводы, избегайте алкоголя и седативных средств, соблюдайте режим. Алкоголь и седативные угнетают дыхательный драйв и заметно ухудшают ночную гипоксию.",
    // ---------- h3 ----------
    "hb.h3.s1.h" to "Три степени",
    "hb.h3.s1.b" to "Лёгкая: непрерывный озноб, в сознании, действует самостоятельно. Средняя: озноб прекращается, спутанность или невнятная речь, неловкие движения. Тяжёлая: без сознания, пульс и дыхание слабые или не определяются.",
    "hb.h3.s2.h" to "Критическая ошибка трактовки",
    "hb.h3.s2.b" to "Прекращение озноба часто принимают за улучшение; на самом деле это признак отказа теплопродукции и перехода из средней степени в тяжёлую. Именно здесь происходит большинство ошибок на месте.",
    "hb.h3.s3.h" to "Принципы помощи",
    "hb.h3.s3.b" to "Первое: укрыть от ветра и холода, изолировать от земли. Второе: сменить мокрую одежду и укутать. Третье: при средней и тяжёлой степени избегать грубых перемещений и энергичных движений конечностями — холодное сердце легко впадает в аритмию. Четвёртое: сначала согревать туловище, а не конечности, чтобы холодная кровь не приливала к центру.",
    "hb.h3.s4.h" to "Чего делать нельзя",
    "hb.h3.s4.b" to "Не давайте алкоголь и кофеин при средней и тяжёлой гипотермии, не заставляйте идти при тяжёлой гипотермии и не растирайте конечности. Тяжёлая гипотермия — неотложное состояние, нужна срочная эвакуация.",
    // ---------- h4 ----------
    "hb.h4.s1.h" to "Распознавание",
    "hb.h4.s1.b" to "Поверхностное отморожение: кожа бледная, восковидная, ещё упругая при нажатии, боль жгучая или колющая; после согревания функция восстанавливается. Глубокое: кожа твёрдая как дерево, нечувствительная, возможны геморрагические пузыри; после согревания отёк и почернение — тяжёлая травма.",
    "hb.h4.s2.h" to "Стандартное согревание",
    "hb.h4.s2.b" to "Погрузить в воду 37–40 °C примерно на 30 минут, пока кожа не покраснеет и не размягчится. Никогда не растирать снегом, не держать у огня, не использовать грелку и не применять прямые источники тепла: отмороженные ткани не чувствуют и легко обжигаются. Согревание очень болезненно и требует обезболивания.",
    "hb.h4.s3.h" to "Ловушка решения о согревании",
    "hb.h4.s3.b" to "Если после согревания участок может снова замёрзнуть, не согревайте его на месте. Цикл замерзание–оттаивание–повторное замерзание разрушает гораздо больше тканей, чем пребывание в замёрзшем состоянии. Правильно — защитить участок, избегать трения и как можно быстрее спуститься туда, где можно оставаться в тепле.",
    "hb.h4.s4.h" to "Дальнейший уход",
    "hb.h4.s4.b" to "Не вскрывайте пузыри. Накладывайте стерильную салфетку свободно и держите участок в тепле и сухости. Не нагружайте повреждённую часть. Отдалённые последствия — чувствительность к холоду, парестезии, нарушение потоотделения — могут сохраняться месяцами.",
    // ---------- h5 ----------
    "hb.h5.s1.h" to "Как нести ледоруб и двигаться",
    "hb.h5.s1.b" to "В движении держите ледоруб в руке со стороны склона, клюв назад, головка вперёд — положение «ледоруб-посох». Смысл в том, что можно сразу перейти в положение самозадержания, не перехватывая.",
    "hb.h5.s2.h" to "Четыре точки положения самозадержания",
    "hb.h5.s2.b" to "Первое: лечь на живот лицом к склону. Второе: держать ледоруб поперёк груди. Третье: одна рука над головой у клюва, другая на древке. Четвёртое: вонзить клюв в снег и надавить весом тела, одновременно подняв обе ноги от снега носками вверх.",
    "hb.h5.s3.h" to "Почему нужно поднимать ноги",
    "hb.h5.s3.b" to "Это самая частая ошибка новичков. Как только нога касается снега, она разгружает ледоруб, эффективность задержания падает, возможны травмы голеностопа и колена. Тормоз работает за счёт веса тела, передаваемого через клюв в снег.",
    "hb.h5.s4.h" to "Скольжение головой вперёд",
    "hb.h5.s4.b" to "Здесь клюв не входит в снег эффективно, а удар головой очень опасен. Первое действие — перекатиться корпусом в положение на животе ногами вниз по склону, и уже затем выполнять задержание.",
    "hb.h5.s5.h" to "Как тренироваться",
    "hb.h5.s5.b" to "Повторяйте на пологом склоне с чистым выкатом, мягким снегом и инструктором на страховке, пока движение не станет автоматическим. Обратите внимание на снег: мягкий останавливает быстро, а твёрдый и лёд дают гораздо более длинное скольжение.",
    // ---------- h6 ----------
    "hb.h6.s1.h" to "Французская техника (плоская стопа)",
    "hb.h6.s1.b" to "Все зубья, перпендикулярные опоре, касаются склона одновременно, стопа ставится плашмя, передние зубья не вбиваются. Нагрузка распределяется по ноге и всему телу, поэтому это самый экономичный способ; подходит для малых и средних углов и плотного снега, основной приём на длинных снежных склонах.",
    "hb.h6.s2.h" to "Немецкая техника (передние зубья)",
    "hb.h6.s2.b" to "Передние зубья вбиваются вертикально в лёд, икра работает непрерывно. Подходит для склонов круче 45° и ледовых стен, но очень энергозатратна и долго не выдерживается. Вес тела сосредоточен на двух-трёх передних зубьях.",
    "hb.h6.s3.h" to "Смешанная техника (американская)",
    "hb.h6.s3.b" to "Одна нога ставится плашмя на склон как опора, другая работает на передних зубьях, попеременно. Применяется на переходном рельефе между средним и крутым, связывает французскую и немецкую технику.",
    "hb.h6.s4.h" to "Траверс и «утиный шаг»",
    "hb.h6.s4.b" to "На снежном траверсе используйте «утиный шаг»: пятки вместе, носки развёрнуты наружу, чтобы все кошки лежали на склоне и вес не приходился только на внутренние зубья. Слегка наклоняйтесь к склону.",
    "hb.h6.s5.h" to "Совместимость ботинок и кошек (предел безопасности)",
    "hb.h6.s5.b" to "Мягкие ботинки B1 с кошками на ремнях C1; полужесткие B2 с C2 (ремень спереди, защёлка сзади); жёсткие B3 с C3 на полной защёлке. Кошки с полной защёлкой на мягком ботинке деформируют его, защёлки теряют захват, и на крутом склоне кошки могут слететь.",
    // ---------- h7 ----------
    "hb.h7.s1.h" to "Работа ледорубом",
    "hb.h7.s1.b" to "Бейте от кисти, а не рубите всей рукой. Клюв входит вертикально; чёткий сухой звук — хорошая постановка, глухой обычно означает неверный угол или трухлявый лёд. Не частите с ударами: разбитая стена отслаивается пластинами, которые уже не держат.",
    "hb.h7.s2.h" to "Забивание зубьев и три точки опоры",
    "hb.h7.s2.b" to "Согните колено, поднимите ногу, вбейте передние зубья вертикально. Стабилизируйте обе ноги перед ударом и всегда сохраняйте три надёжные точки опоры, прежде чем перемещать четвёртую. Ровный ритм важнее величины шага.",
    "hb.h7.s3.h" to "Градация WI для водного льда",
    "hb.h7.s3.b" to "WI1: лёд малого угла, проходится без инструмента. WI2: непрерывный лёд около 60° с наплывами и хорошей страховкой. WI3: непрерывные 60–75°, страховка обычно хорошая, но нагрузки высокие. WI4: почти вертикально с короткими вертикальными участками, страховка может быть плохой. WI5: непрерывно вертикально, страховка плохая, очень тяжело. WI6: непрерывно вертикально с карнизами и очень плохой страховкой.",
    "hb.h7.s4.h" to "Почему условия важнее категории",
    "hb.h7.s4.b" to "Один и тот же маршрут сильно меняется от температуры, солнца и сезона: утренний лёд твёрдый и требует точной постановки, а к полудню растаявший снег превращается в трухлявый лёд, который не держит. Категория — лишь ориентир; оценивайте лёд в этот день.",
    "hb.h7.s5.h" to "Пределы безопасности",
    "hb.h7.s5.b" to "Ледолазание требует опытного страхующего, надёжной точки страховки и плана отхода. Падения здесь гораздо тяжелее, чем в спортивном лазании, а ледобуры могут вырваться под нагрузкой — в этом ключевое отличие от скал.",
    // ---------- h8 ----------
    "hb.h8.s1.h" to "Восьмёрка с повторным прохождением",
    "hb.h8.s1.b" to "Стандартный узел для привязывания к системе. Его легко увидеть и проверить, и после нагрузки он относительно легко развязывается. Это обычное соединение на леднике и на смешанных маршрутах.",
    "hb.h8.s2.h" to "Схватывающий узел «удавка» (clove hitch)",
    "hb.h8.s2.b" to "Соединяет верёвку с карабином и быстро регулирует длину одной рукой. Применяется для самостраховки на станции, позволяя двигаться вокруг площадки.",
    "hb.h8.s3.h" to "Двойной рыбацкий узел",
    "hb.h8.s3.b" to "Соединяет две верёвки или превращает шнур в замкнутую петлю прусика. Он очень стабилен и почти не распускается, но после нагрузки развязывается труднее.",
    "hb.h8.s4.h" to "Прусик",
    "hb.h8.s4.b" to "Узел трения: держит верёвку под нагрузкой и скользит без неё. Применяется для подъёма, как дублирование и в системах механического преимущества. Надёжность зависит от диаметра шнура и числа витков — проверьте его, прежде чем полагаться.",
    "hb.h8.s5.h" to "Привычка проверять",
    "hb.h8.s5.b" to "Оставляйте достаточный кончик после каждого узла (обычно не менее десяти диаметров верёвки) и проверяйте друг друга. Узлы — единственная часть страховочной цепи, сделанная руками и не прошедшая заводской контроль.",
    // ---------- h9 ----------
    "hb.h9.s1.h" to "Четыре принципа SRENE",
    "hb.h9.s1.b" to "Solid (прочно): каждая точка выдерживает расчётную нагрузку. Redundant (дублирование): больше одной независимой точки. Equalized (выравнивание): нагрузка распределена разумно и не зависит от одной точки. No Extension (без удлинения): при отказе точки система не получает рывок с удлинением.",
    "hb.h9.s2.h" to "EARNEST",
    "hb.h9.s2.b" to "Дополняет SRENE: Efficient (собирается без возни), Anchored (надёжно закреплено), Strong (прочно), Timely (собирается быстро, сокращая время под риском). Это ближе к тому, как станцию оценивают на реальном рельефе.",
    "hb.h9.s3.h" to "Почему важно No Extension",
    "hb.h9.s3.b" to "Если между точками есть слабина, при отказе остальные получают внезапный рывок, намного больший статической нагрузки. Выравнивание и предварительный натяг убирают этот рывок из системы.",
    "hb.h9.s4.h" to "Разные среды — разные методы",
    "hb.h9.s4.b" to "На снегу: снежные анкеры, «мертвецы», Т-образные траншеи, но надёжность сильно зависит от качества снега и качества закопки. На льду: ледобуры, с проверкой на сотовый лёд и пустоты. На скалах: закладки и крючья. Никогда не судите одну среду чужим чутьём.",
    // ---------- h10 ----------
    "hb.h10.s1.h" to "Шаг первый: задержать падение",
    "hb.h10.s1.b" to "Когда человек срывается, его вес мгновенно переходит на верёвку и на партнёра. Партнёр должен сразу войти в самозадержание и держать. Это основа всей цепочки спасения.",
    "hb.h10.s2.h" to "Шаг второй: построить точку страховки",
    "hb.h10.s2.b" to "Удерживая задержание, постройте независимую точку страховки из снежного анкера, закопанного ледоруба или Т-образной траншеи по принципам SRENE. Важно: отпускать задержание нельзя, пока точка не готова.",
    "hb.h10.s3.h" to "Шаг третий: перенести нагрузку",
    "hb.h10.s3.b" to "Перенесите вес сорвавшегося с собственного тела на точку страховки. Обычно для этого закрепляют нагруженную верёвку на точке прусиком или регулируют «удавкой». Только после переноса руки свободны.",
    "hb.h10.s4.h" to "Шаг четвёртый: подъём",
    "hb.h10.s4.b" to "Используйте систему Z 3:1 (Z-drag): прусик и блок на нагруженной верёвке, работающие против точки страховки и дающие тройной выигрыш в силе. Это просто, требует мало снаряжения, собирается быстро и является стандартом спасения из трещины.",
    "hb.h10.s5.h" to "Что делает сорвавшийся",
    "hb.h10.s5.b" to "Сохраняйте спокойствие, не давайте верёвке ещё больше пропиливать край трещины, пытайтесь подняться прусиком и постоянно говорите с поверхностью. Команда должна заранее отрепетировать всю последовательность — только так она выполняется.",
    // ---------- h11 ----------
    "hb.h11.s1.h" to "Крутизна склона: самый сильный фактор",
    "hb.h11.s1.b" to "Около 96 % лавин сходят на склонах 30–50°, большинство — между 34 и 45°. Ниже примерно 30° слишком полого для лавин из пластов; выше примерно 50° снег не накапливает толстые пласты. Значит, самые опасные склоны часто те, что не кажутся крутыми.",
    "hb.h11.s2.h" to "Уровни опасности 1–5",
    "hb.h11.s2.b" to "Слабый / умеренный / значительный / большой / чрезвычайный. Статистически происшествия концентрируются на уровне 3, значительном: условия кажутся разумными, склон — проходимым, и многие выходят на лавинный рельеф. На уровнях 4 и 5 почти все остаются дома, поэтому доля происшествий падает.",
    "hb.h11.s3.h" to "Триада и правила движения",
    "hb.h11.s3.b" to "Бипер, щуп и лопата должны быть при себе и использоваться уверенно. На лавинном рельефе расходитесь, пересекайте по одному, ставьте наблюдателя в безопасном месте и планируйте путь отхода так, чтобы вся группа не оказалась под лавиной одновременно.",
    "hb.h11.s4.h" to "Привычки решений",
    "hb.h11.s4.b" to "Перед выходом смотрите местный лавинный прогноз и погоду последних дней. Продолжайте замечать трещины, звуки «вумпф» и свежие ветровые пласты. При явном сомнении выбирайте более консервативный вариант. В лавинных делах привычки спасают больше жизней, чем знания.",
    // ---------- h12 ----------
    "hb.h12.s1.h" to "Ледорубы: тип B и тип T",
    "hb.h12.s1.b" to "Тип B (базовый) имеет более прямое древко, для движения по снегу и самозадержания; он держит нагрузки ходьбы и задержания. Тип T (технический) имеет древко, которое можно вбить в лёд и нагрузить рывком, для крутого льда. Использовать ледоруб B для работы T — явная ошибка.",
    "hb.h12.s2.h" to "Кошки: C1 / C2 / C3",
    "hb.h12.s2.b" to "C1 на ремнях, для мягких ботинок; C2 с ремнём спереди и защёлкой сзади, для полужестких; C3 на полной защёлке, для жёстких. Более высокий класс — больше жёсткости, но и более требователен к ботинку. Неверное сочетание может привести к сходу кошек.",
    "hb.h12.s3.h" to "Ботинки: одинарные и двойные",
    "hb.h12.s3.b" to "Одинарные ботинки легки и подвижны, подходят для средней высоты и ледолазания. Двойные имеют съёмный внутренний сапог, который можно держать в тепле ночью или сушить в спальнике, не давая ему замёрзнуть, — ключевое преимущество на многодневных высотных маршрутах.",
    "hb.h12.s4.h" to "Три вещи, которые легко забыть",
    "hb.h12.s4.b" to "Очки с UV400: снег отражает ультрафиолет и может вызвать снежную слепоту. Солнцезащитный крем с высоким фактором: УФ заметно растёт с высотой, а ожоги очень часты. Запасной слой утепления и толстые перчатки: их надо держать сухими, потому что влага — предпосылка гипотермии.",
    "hb.h12.s5.h" to "Привычка проверять",
    "hb.h12.s5.b" to "Перед каждым выходом проверяйте защёлки кошек, клюв и древко ледоруба, прострочку обвязки, износ верёвки и трещины каски. Снаряжение отказывает в самый неподходящий момент, а цена проверки почти нулевая.",
    // ---------- h13 ----------
    "hb.h13.s1.h" to "Распространённость и кто болеет",
    "hb.h13.s1.b" to "Высотная болезнь не связана надёжно с возрастом или физической формой. Данные показывают, что 50–65 % людей выше 4 000 м заболевают острой горной болезнью, а на 2 500–4 300 м — 25–43 %. У пожилых треккеров на средней высоте (средний возраст 65 лет) частота сходна с молодыми. При наличии болезней лёгких риск несколько выше.",
    "hb.h13.s2.h" to "AMS: распознавание и помощь",
    "hb.h13.s2.b" to "Первый симптом обычно головная боль плюс хотя бы один из признаков: тошнота и рвота, слабость, головокружение, плохой сон. Помощь: прекратить подъём и отдыхать на текущей высоте до улучшения; безрецептурный анальгетик, например ибупрофен, снимает головную боль; при сохранении или ухудшении симптомов немедленно спускаться. Спуск всего на 500–1 000 м часто даёт заметное улучшение.",
    "hb.h13.s3.h" to "HACE: распознавание и помощь",
    "hb.h13.s3.b" to "Обычно следует за AMS: нарушение сознания (спутанность, сонливость, ступор), атаксия (неустойчивая походка, трудно идти), сильная головная боль, не отвечающая на лекарства, раздражительность или галлюцинации. Помощь: немедленный спуск не менее чем на 1 000 м; кислород; дексаметазон под контролем врача (8–10 мг вначале, затем 4 мг каждые 6 часов); портативная гипербарическая камера, если спуск задерживается; эвакуация в медицинское учреждение как можно скорее.",
    "hb.h13.s4.h" to "HAPE: распознавание и помощь",
    "hb.h13.s4.b" to "Обычно возникает выше 2 500 м из-за чрезмерной гипоксической вазоконстрикции лёгких. Признаки: одышка в покое или при лёгкой нагрузке (хуже ночью), постоянный кашель с пенистой или розовой мокротой, крайняя слабость, стеснение в груди, тахикардия, синюшные губы, спутанность. Помощь: немедленный спуск не менее чем на 1 000 м; кислород; нифедипин или силденафил под контролем врача; дексаметазон в тяжёлых случаях; портативная гипербарическая камера; держать пациента в тепле и покое, чтобы снизить потребность в кислороде.",
    "hb.h13.s5.h" to "Сочетание и профилактика",
    "hb.h13.s5.b" to "Около 13–20 % случаев HAPE сопровождаются HACE, поэтому при любых признаках отёка лёгких проверяйте сознание и походку. Профилактика: выше 3 000 м держите суточный прирост высоты ночёвки в пределах 500 м (некоторые источники советуют более консервативные 300–500 м), планируйте дни акклиматизации, пейте достаточно, но без переизбытка, избегайте алкоголя и седативных, избегайте перегрузок, применяйте ацетазоламид или дексаметазон (для профилактики тяжёлых форм) либо нифедипин или силденафил (для профилактики HAPE) по назначению врача и контролируйте пульсоксиметром.",
    // ---------- h14 ----------
    "hb.h14.s1.h" to "Защита головы и лица",
    "hb.h14.s1.b" to "Шляпа от солнца и пустынная шляпа закрывают голову, лицо и шею. Балаклава оставляет открытыми только глаза и рот, её используют на высоте против отморожения лица. Шапка из флиса должна закрывать уши и «дышать», чтобы голова не отсыревала. Выбирайте бафф с UV-защитой, закрывающий большую часть открытой кожи.",
    "hb.h14.s2.h" to "Верх: система трёх слоёв",
    "hb.h14.s2.b" to "Первый слой: лёгкое термобельё, отводящее влагу, никогда не хлопок. Средний слой: флис или синтетическая утеплённая куртка; вариант с капюшоном универсальнее. Внешний слой: мембрана GORE-TEX (непромокаемая, дышащая, ветрозащитная), проверенная на совместимость с каской; хардшелл для экстремального ветра и снега. Добавьте пуховую куртку для сильного холода: упругость пуха 800 и выше, с капюшоном, пуховой, не синтетический наполнитель.",
    "hb.h14.s3.h" to "Низ и гамаши",
    "hb.h14.s3.b" to "База: термобельё, флисовые штаны и штаны с мембраной GORE-TEX. Тяжёлые синтетические утеплённые штаны для выходов в лагеря; хардшелл средней плотности от дождя, снега и ветра; лёгкие быстро сохнущие треккинговые штаны поверх утеплителя. Хлопок исключить полностью: полиэстер или меринос. Для 8 000 м пуховые штаны должны быть с пуховым наполнителем, с полными боковыми молниями для туалета и размером поверх всех слоёв. Длинные гамаши не дают снегу попадать в ботинки.",
    "hb.h14.s4.h" to "Система перчаток",
    "hb.h14.s4.b" to "Минимум три пары: тонкие шерстяные для мелкой работы, ветрозащитные и стойкие к истиранию (выбирайте совместимые с сенсорным экраном для устройств) и толстые (гидские высотные, софтшелл с кожаной ладонью). Добавьте вершинные перчатки SUMMIT: непромокаемый дышащий верх, съёмный синтетический вкладыш.",
    "hb.h14.s5.h" to "Обувь и носки",
    "hb.h14.s5.b" to "Вершинный ботинок для 8 000 м требует съёмного утеплённого внутреннего сапога, прочного непромокаемого трёхслойного ламинированного верха, защиты от проколов и непромокаемой дышащей мембраны. Ботинок для 6 000 м должен быть лёгким, удобным и с хорошим сцеплением; рекомендуется GORE-TEX. Носки — синтетические (без хлопка), до колена, с балансом тепла и кровообращения на длинных днях; возьмите и тонкие треккинговые носки, чтобы меньше натирать. Лагерные ботинки и тапочки — для лагеря: тёплые, непромокаемые, нескользящие.",
    // ---------- h15 ----------
    "hb.h15.s1.h" to "Ледоруб и кошки",
    "hb.h15.s1.b" to "Ледоруб должен быть с прямым древком и клювом, годиться как опора при ходьбе, для самозадержания и вырубания ступеней. Длина по росту: ниже примерно 157 см — 50 см; 157–170 см — 55 см; 173–180 см — 60 см; выше 183 см — 65–70 см. Кошки — стальные, 12 зубьев, с антиподлипными пластинами, надёжно закреплённые ремнями или защёлкой, обязательно по размеру ботинка.",
    "hb.h15.s2.h" to "Снаряжение для лазания и спасения",
    "hb.h15.s2.b" to "Обвязка — альпинистская (лёгкие стропы), размером поверх верхней одежды. Спусковое устройство: восьмёрка или корзинка ATC. Жумар для подъёма по верёвке. Карабины — с муфтой (с защёлкой, надёжнее винтовой) и без муфты; берите крупные для обвязки. Стропа 120 см. Шнур для прусика обязателен: это основа схватывающего узла и систем спасения из трещины.",
    "hb.h15.s3.h" to "Навигация, связь и свет",
    "hb.h15.s3.b" to "Часы-альтиметр обычно совмещают альтиметр, барометр и компас, с будильником шторма, который срабатывает при быстром падении давления в течение трёх часов. GPS-трекер позволяет другим следить за вашим положением. Спутниковый телефон звонит и пишет через спутник, нужна предоплаченная SIM. Каска должна быть лёгкой, вентилируемой, легко регулироваться, с усиленным пенопластом и креплением для налобного фонаря; запасной фонарь 400–500 лм и больше (мощные модели явно выигрывают в непогоду), лучше влагозащищённый.",
    "hb.h15.s4.h" to "Системы сна и переноски",
    "hb.h15.s4.b" to "Для 6 000 м выбирайте пуховой спальник (синтетика тяжелее); для 8 000 м — пуховой для экстремального холода. Пенковый коврик добавляет тепло при сне, на леднике или мёрзлой земле; надувной пуховой матрас добавляет комфорт; вкладыш добавляет тепло и сохраняет спальник чистым. Вершинный рюкзак: 35–50 литров полезного объёма, желательно с карманами для кошек и кислородных баллонов. Баул: 90–120 литров, непромокаемый и прочный для перевозки. Гермомешки защищают паспорт и документы; средние и большие удобны, чтобы отделить грязную одежду.",
    "hb.h15.s5.h" to "Солнцезащита и мелочи",
    "hb.h15.s5.b" to "Крем с высоким содержанием оксида цинка, SPF 50, защищает от солнца и снежных ожогов; гигиеническая помада должна быть с цинком и умеренно стойкой к поту (SPF 30–50). Химические грелки для рук и ног применяйте только в закрытом пространстве (перчатки, ботинки): на воздухе они разогреваются примерно до 74 °C и могут вызвать ожог или возгорание. Также возьмите бутылку 1 л, термос 1–1,5 л, столовые приборы, ножницы для ногтей, ремонтный скотч и пауэрбанк.",
    // ---------- h16 ----------
    "hb.h16.s1.h" to "Страховка",
    "hb.h16.s1.b" to "По прибытии в Катманду нужно передать организаторам копию страхового полиса. Он должен покрывать медицинские расходы, экстренную эвакуацию и другие виды защиты, требуемые для этой экспедиции. Уточните объём и условия до выезда.",
    "hb.h16.s2.h" to "Отмена рейсов и лишние ночи",
    "hb.h16.s2.b" to "Кроме случаев, вызванных организатором, отмена рейса не даёт права на компенсацию. Если отмена (внутренняя или международная) произошла по личным причинам или из-за погоды и привела к лишним ночам, проживание и питание — за ваш счёт: например, при отмене рейсов Катманду–Лукла участники оплачивают дополнительное проживание сами. В высокий сезон рейсы в Луклу могут выполняться из Рамечхапа (около 140 км юго-восточнее); участники обязаны принять изменённую схему.",
    "hb.h16.s3.h" to "Багаж и портеры",
    "hb.h16.s3.b" to "В разделе включённых услуг указан лимит багажа. Вес сверх лимита на внутренних рейсах оплачивается отдельно; дополнительная переноска портерами тоже платная. Учтите, что весовые ограничения вертолётной переброски могут не позволить вашей сумке лететь с вами в базовый лагерь, и её придётся ждать вне лагеря с лишними ночами — лучше брать возвратный билет с возможностью изменения.",
    "hb.h16.s4.h" to "Дисциплина в лагере и санитарные правила",
    "hb.h16.s4.b" to "Во время экспедиции нельзя посещать другие лагеря, включая лагеря других компаний, и нужно оставаться в отведённой зоне. Правило имеет две цели: предотвратить передачу болезней между лагерями и сократить разрывы в безопасности, сохраняя команду вместе. В базовом лагере также запрещено обсуждать цены на услуги.",
    "hb.h16.s5.h" to "Сертификат о вершине и досрочное завершение",
    "hb.h16.s5.b" to "После успешного восхождения нужно передать чёткое фото или видео, подтверждающее выход на вершину (вершинный гребень или узнаваемый ориентир); иначе Nepal Tourism Board или NMA не выдадут сертификат. Также подаётся собственное заявление и две фотографии на паспорт (рекомендуется белый фон) для сертификата. Если программа завершается раньше из-за окна погоды или хода команды, неиспользованные дни не возвращаются.",
    // ---------- h17 ----------
    "hb.h17.s1.h" to "Спальник базового лагеря (6 000 м)",
    "hb.h17.s1.b" to "Рассчитан примерно на 6 000 м. Выбирайте пух, а не синтетику: при том же тепле синтетика заметно тяжелее и становится обузой при длительных перевозках и переходах.",
    "hb.h17.s2.h" to "Пуховой спальник (8 000 м)",
    "hb.h17.s2.b" to "Рассчитан на 8 000 м, тоже с пуховым наполнителем. Покупайте по температуре комфорта, а не экстремальной; для 8 000 м ориентир обычно -40 °C комфорта.",
    "hb.h17.s3.h" to "Коврики: пенка и надувной пуховой",
    "hb.h17.s3.b" to "Пенковый коврик добавляет тепло при сне на леднике или мёрзлой земле; он прост и не прокалывается. Надувной пуховой матрас удобнее, но требует защиты от проколов и ремкомплекта. На высоте обычно используют оба.",
    "hb.h17.s4.h" to "Вкладыш",
    "hb.h17.s4.b" to "Вкладыш кладут внутрь спальника, чтобы добавить тепла и не пачкать спальник потом и грязью. В длинных экспедициях он сильно снижает частоту стирок — дёшево и очень полезно.",
    "hb.h17.s5.h" to "Подушка",
    "hb.h17.s5.b" to "Плюс — экономия места в рюкзаке; минусы — тепло, сползание внутри спальника и плохая поддержка при перекачивании. В целом: лучше, чем ничего, но это не настоящая подушка — не ждите многого.",
    // ---------- h18 ----------
    "hb.h18.s1.h" to "Вершинный рюкзак (35–50 л)",
    "hb.h18.s1.b" to "Для однодневного выхода, с приоритетом лёгкости. Предпочитайте модель с отдельными карманами для кошек и кислородных баллонов, чтобы острые предметы не тёрли остальное снаряжение. Используется в день вершины.",
    "hb.h18.s2.h" to "Баул (90–120 л)",
    "hb.h18.s2.b" to "Конструкция с одной молнией, чтобы уложить всё снаряжение для групповой перевозки. Ткань должна быть непромокаемой и прочной, чтобы выдержать долгую перевозку, погрузку и переноску портерами.",
    "hb.h18.s3.h" to "Гермомешки",
    "hb.h18.s3.b" to "Защищают содержимое от снега и воды; паспорт и документы должны быть внутри. Средние и большие мешки удобны также для отделения грязной одежды от чистой.",
    "hb.h18.s4.h" to "Перевес багажа и дополнительные портеры",
    "hb.h18.s4.b" to "В разделе включённых услуг указан лимит багажа, который обычно покрывает программу. Всё сверх — перевес, требующий дополнительной переноски, оплачивается отдельно.",
    "hb.h18.s5.h" to "Багаж может не полететь с вами",
    "hb.h18.s5.b" to "Во время экспедиции весовые ограничения вертолётной переброски могут не позволить сумке лететь с вами в базовый лагерь. Участники могут оказаться в Катманду раньше своих вещей и понести дополнительные расходы на проживание.",
    // ---------- h19 ----------
    "hb.h19.s1.h" to "Солнцезащитный крем",
    "hb.h19.s1.b" to "Выбирайте формулу с высоким содержанием оксида цинка и сильной защитой от прямого солнца и отражения от снега — от солнечных и снежных ожогов. Ориентир: SPF 50 (например, Banana Boat или Nivea SPF 50).",
    "hb.h19.s2.h" to "Грелки для рук и ног",
    "hb.h19.s2.b" to "Грелки для пальцев и стоп на воздухе разогреваются примерно до 74 °C (165 °F) — достаточно для низкотемпературного ожога. Используйте только в закрытом пространстве: в перчатках, рукавицах и ботинках. Никогда в вентилируемой обуви или перчатках.",
    "hb.h19.s3.h" to "Увлажняющий крем и гигиеническая помада",
    "hb.h19.s3.b" to "Лосьон с высоким содержанием цинка и умеренной стойкостью к поту помогает защитить кожу от солнца и снега; то же относится к гигиенической помаде, ориентир SPF 30–50. Перед покупкой спросите совета.",
    "hb.h19.s4.h" to "Посуда и питание",
    "hb.h19.s4.b" to "Обязательно: бутылка для воды (1 л), термос (1–1,5 л), ложка и вилка, миска. Термос заметно улучшает питьё в верхнем лагере и заслуживает приоритета.",
    "hb.h19.s5.h" to "Гигиена и мелочи",
    "hb.h19.s5.b" to "Личное: туалетная бумага, влажные салфетки, зубная паста, щётка, мыло, шампунь, полотенце, мешки для мусора. Разное: ножницы для ногтей, зонт или дождевик, грелка, мочеприёмник (1 л), ремкомплект с армированным скотчем, фотоаппарат, пауэрбанк.",
    // ---------- h20 ----------
    "hb.h20.s1.h" to "Важное примечание к этому списку",
    "hb.h20.s1.b" to "Приведённый список лекарств составлен врачом, сопровождающим высотную команду SEVEN SUMMIT TREKS, и отражает реальную экспедиционную практику. Но важно понимать:\n\n• Позиции и дозы — справочные значения, а не назначение.\n• Каждый участник отличается по возрасту, весу, истории болезней, аллергиям и принимаемым препаратам; врач должен оценить и подтвердить всё на месте.\n• Рецептурные препараты (ацетазоламид, дексаметазон, нифедипин, силденафил, диазепам, кодеин и другие) нельзя принимать без назначения врача.\n• Покажите этот список врачу до выезда: он должен скорректировать его по пунктам и установить ваши личные дозы.\n\nЭтот текст — учебный материал, а не медицинская рекомендация.",
    "hb.h20.s2.h" to "Состав аптечки (список врача команды, справочные значения)",
    "hb.h20.s2.b" to "Может понадобиться: ибупрофен, антибиотики, ацетазоламид, парацетамол, пластыри, полоски для закрытия ран, йод, диазепам, цетиризин, электролиты, а также рецептурные средства при сердцебиении и тревоге, головной и загрудинной боли, одышке и инфекции (например, пропранолол, кодеин, соталол, азитромицин).\n\nЕщё раз: это только справочный диапазон; реальные препараты и дозы должен подтвердить врач для конкретного человека.",
    "hb.h20.s3.h" to "Контроль кислорода в крови",
    "hb.h20.s3.b" to "Используйте пульсоксиметр для контроля сатурации, особенно при наличии высотной болезни в анамнезе. Тренд важнее одного измерения; записывайте в фиксированное время (утром и перед сном) и сопоставляйте с симптомами.",
    "hb.h20.s4.h" to "Медицинская поддержка в базовом лагере",
    "hb.h20.s4.b" to "При высотной болезни SEVEN SUMMIT TREKS разворачивает медицинские палатки в базовых лагерях основных вершин Непала, где работают высотные врачи, с системной процедурой оценки клиентов и вмешательства по необходимости.",
    "hb.h20.s5.h" to "Страховка и экстренная эвакуация",
    "hb.h20.s5.b" to "По прибытии в Катманду клиенты должны передать SEVEN SUMMIT TREKS копию страхового полиса. Он должен покрывать медицинские расходы, экстренную эвакуацию и другие виды защиты на время программы.",
    "hb.h20.s6.h" to "Принципы приёма лекарств",
    "hb.h20.s6.b" to "Профилактические препараты (ацетазоламид, дексаметазон, нифедипин, силденафил) требуют предварительной консультации врача; дозы здесь справочные. Не сочетайте самостоятельно обезболивающие и седативные: алкоголь и седативные угнетают дыхание и ухудшают гипоксию. При ухудшении спускайтесь, а не увеличивайте дозу: спуск — единственное надёжно работающее лечение, и никакой препарат его не заменяет.",
    // ---------- h21 ----------
    "hb.h21.s1.h" to "Кто больше предрасположен к AMS",
    "hb.h21.s1.b" to "Острая горная болезнь может развиться у любого; она не связана надёжно с возрастом или формой. Пожилые треккеры на средней высоте (в среднем 65 лет) болеют с той же частотой, что и молодые. Болезни лёгких могут немного повышать риск. Реальные переменные — слишком быстрый подъём, слишком высокие ночёвки и индивидуальная физиологическая реакция на гипоксию.",
    "hb.h21.s2.h" to "Факторы риска HACE",
    "hb.h21.s2.b" to "Быстрый подъём выше 2 000 м без акклиматизации; перенесённые AMS или HAPE; текущий HAPE (около 13–20 % случаев HAPE дают HACE); возможные анатомические факторы, например внутричерепной объём, хотя механизм не до конца ясен. В отличие от HAPE, для HACE специфическая генетическая предрасположенность не подтверждена.",
    "hb.h21.s3.h" to "Факторы риска HAPE",
    "hb.h21.s3.b" to "Быстрый подъём (выше 2 500 м без акклиматизации); перенесённый HAPE, что повышает риск повторения; наследственная склонность к чрезмерной лёгочной вазоконстрикции; перегрузки на высоте; болезни лёгких или сердца; холод, усиливающий гипоксию; некоторые исследования показывают, что чаще страдают молодые, возможно потому, что работают на пределе.",
    "hb.h21.s4.h" to "Рабочий ритм профилактики",
    "hb.h21.s4.b" to "Выше 3 000 м держите суточный прирост высоты ночёвки в пределах 500 м (300–500 м консервативнее); планируйте дни акклиматизации; пейте достаточно, но не чрезмерно; избегайте алкоголя и седативных; избегайте перегрузок; контролируйте пульсоксиметром; применяйте профилактические препараты по назначению врача, когда это показано.",
    "hb.h21.s5.h" to "Маршрут и есть профилактика",
    "hb.h21.s5.b" to "Грамотные программы снижают эти риски за счёт контролируемого профиля подъёма и постепенного набора. Выбирая программу, ставьте профиль подъёма первым критерием, а не только дни и цену.",
    // ---------- h22 ----------
    "hb.h22.s1.h" to "Страховка путешественника",
    "hb.h22.s1.b" to "По прибытии в Катманду клиенты должны передать SEVEN SUMMIT TREKS копию полиса, покрывающего медицинские расходы, экстренную эвакуацию и другие виды защиты.",
    "hb.h22.s2.h" to "Отмена рейсов и лишние ночи",
    "hb.h22.s2.b" to "Кроме случаев по вине самой компании, отмена не даёт компенсации. Лишние ночи из-за личных причин или непогоды — за счёт клиента: например, проживание и питание в Лукле или Катманду при отмене рейсов Катманду–Лукла. Если авиакомпания или CAAN меняют рейсы, участники обязаны принять новую схему (в высокий сезон рейсы в Луклу могут вылетать из Рамечхапа).",
    "hb.h22.s3.h" to "Доступ в лагеря и конфиденциальность цен",
    "hb.h22.s3.b" to "Во время экспедиции нельзя посещать другие лагеря; клиенты должны оставаться в отведённой зоне: это предупреждает распространение болезней, защищает санитарный протокол и снижает угрозы безопасности. В базовом лагере также запрещены визиты в лагеря других компаний и обсуждение цен на услуги.",
    "hb.h22.s4.h" to "Фото или видео с вершины",
    "hb.h22.s4.b" to "После успешного восхождения участники должны передать чёткое фото или видео, подтверждающее выход на вершину, например вершинный гребень или узнаваемый ориентир. Только после этого начинается оформление сертификата.",
    "hb.h22.s5.h" to "Заявление и сертификат",
    "hb.h22.s5.b" to "Участники предоставляют две фотографии на паспорт (рекомендуется белый фон) для вклейки в сертификат. Также заполняется собственное заявление со всеми сведениями, требуемыми Министерством культуры, туризма и гражданской авиации; его можно заполнить в базовом лагере или после экспедиции.",
    // ---------- h23 ----------
    "hb.h23.s1.h" to "Проваленное учение по спасению из лавины",
    "hb.h23.s1.b" to "Восемь курсантов прошли двухдневный курс по биперам на горе Бейкер. Полтора дня они тренировались находить закопанные в снег сумки и быстро прогрессировали, пока не стали находить и откапывать цель за три минуты или меньше — лучше сенбернара.\n\nНа итоговом испытании восемь человек составили одну команду, руководителем назначили Тома, лыжника-телемаркера. Инструктор дал команде указания по спасению, например выделить человека наблюдать за свежими подвижками. Но Том ничего не сказал о том, что должен делать руководитель спасательных работ: он просто кивнул и уверенно пошёл вверх по склону.\n\nПрибежал лыжник с криком, что партнёр засыпан большой лавиной. Они бросили рюкзаки, послушали биперы и выстроились по склону, как дети на поисках пасхальных яиц. Шесть человек сошлись на самом громком сигнале, и живую цель в ложбине на другой стороне нашли слишком поздно — человек погиб.\n\nПровал был не техническим. Все восемь уверенно работали с биперами; не хватило руководства: никто не взял общее управление, никто не распределил роли, никто не остался наблюдателем.",
    "hb.h23.s2.h" to "Что такое руководство",
    "hb.h23.s2.b" to "Двух одинаковых ответов не бывает. Рабочий подход — начать с того, чего люди ждут от руководителя. Опрос сотен альпинистов дал такой список:\n\n• сильные технические навыки (первая помощь в дикой среде, карта и ориентирование, погода)\n• забота о других\n• хорошее суждение и способность принимать решения\n• надёжность, доверие\n• хорошая коммуникация\n• умение вдохновить людей работать в полную силу\n\nОтсюда определение: руководство — это способность устойчиво вести людей к общим целям, которых нельзя достичь только индивидуальными усилиями.\n\nЭто не составление правил и следование им, а умение строить отношения; не только техника, а сочетание личности и стиля; не только тело и ум, но дух и характер: у хорошего руководителя есть интуиция, сочувствие, здравый смысл и смелость брать ответственность.",
    "hb.h23.s3.h" to "Жёсткие и мягкие навыки",
    "hb.h23.s3.b" to "Планирование, техническое мастерство, трудные решения и управление конфликтом — важные жёсткие навыки, но их недостаточно.\n\nПерелом обычно дают мягкие навыки: построение доверия, ясная речь, баланс разума и интуиции, вдохновение команды. Хорошие руководители не командуют по званию, они опираются на накопленное доверие. Они не требуют от людей блеска, они постоянно поддерживают.\n\n«Руководство — это никогда не просто указание пути; это ведение людей к тому, что важнее всего, лучшим доступным им способом».",
    "hb.h23.s4.h" to "Руководству можно научиться",
    "hb.h23.s4.b" to "Руководство — не дар и не инструмент, а сложная способность решать задачи, и научиться ей может каждый.\n\nПланирование и организация относительно явны и легко тренируются; доверие и интуиция связаны с духом и характером, они сложнее и тоньше, требуют многократной практики в реальной среде.\n\nГлавное: выводите людей в реальную среду и давайте им реальные задачи — только так тренируется хорошее решение. Люди быстро учатся, когда принимают глупое решение или терпят неудачу, решая задачу надеждой и верой вместо фактов; и добиваются успеха, когда решают по фактам.",
    "hb.h23.s5.h" to "К чему приводит некомпетентный руководитель",
    "hb.h23.s5.b" to "Последствия отсутствия руководства на природе конкретны: плохой план промочит всю палатку; поспешное решение вместе со слабой коммуникацией превращает мелкую проблему в серьёзное происшествие; отсутствие человека, способного управлять конфликтом, ведёт переговоры к провалу.\n\nНе ждите, что необученный человек автоматически станет компетентным руководителем в аварийной ситуации.",
    // ---------- h24 ----------
    "hb.h24.s1.h" to "Река Мак-Кинли: решение, которое почти убило",
    "hb.h24.s1.b" to "В 1963 году команда студентов Гарварда спустилась по северной стене горы Мак-Кинли. В головах были стейки и горячий душ: управляющий парковой гостиницей публично поспорил, что они не вернутся живыми, и обещал оплатить всю команду, если они выиграют по глупости.\n\nЛедниковая река резко поднимается и падает вслед за солнцем: талая вода вздувает её днём, после заката она снова подмерзает и минимальна на рассвете. Базовое правило было ясным: дождаться спада воды, примерно 7–8 часов.\n\nУ команды не было терпения. Река была по пояс, быстрая и ревела так, что приходилось кричать. Используя ветки как опору, они пересекли первые десять проток в группах по три и по два. Последняя пара оказалась в воде целиком: одного тянуло как якорь рюкзаком, другого вытащило через галечную косу на основное течение. Остальные были слишком далеко, чтобы помочь.\n\nВ конце оба выползли на мелкую косу. Позднейшая оценка автора: это была не просто юношеская безрассудность; при достаточной тренировке решений, чтобы успокоить импульс и сосредоточиться на «что нам делать», исход мог быть иным.",
    "hb.h24.s2.h" to "Первый принцип: заранее назначить время возвращения",
    "hb.h24.s2.b" to "Оценивайте до того, как решать. Многие решения можно проработать до выхода; не нужно мучиться посреди проблемы.\n\nМетод:\n\n• Зафиксируйте крайнее время окончания активности (у машины, в точке сбора, до темноты).\n• Зафиксируйте максимальное время, которое требует цель.\n• Разница — крайний момент, когда нужно принять решение.\n\nПример: подъём в 06:00 при полной белой мгле. В 07:00 команда поела и собралась. Нужно быть у машины к 18:00; отход из лагеря в белую мглу занимает минимум 4 часа; даже при улучшении погоды вершина и возврат занимают больше 9 часов. 18:00 минус 9 часов даёт 09:00 как крайний момент решения — до этого ещё можно ждать погоды.",
    "hb.h24.s3.h" to "Процесс решения из девяти шагов",
    "hb.h24.s3.b" to "На месте эти девять шагов часто занимают секунды или минуты, но структура та же:\n\n1. Остановитесь: дышите, сосчитайте до десяти, успокойтесь.\n2. Бросьте первый взгляд на варианты.\n3. Ищите нестандартные варианты — думайте вокруг задачи.\n4. Соберите максимум информации по каждому варианту.\n5. Сформулируйте плюсы и минусы каждого.\n6. Взвесьте их, чтобы можно было сравнить.\n7. Выберите вариант, где плюсы перевешивают минусы.\n8. Выполните решение.\n9. Пересматривайте его по мере поступления новой информации.",
    "hb.h24.s4.h" to "Бревенчатый мост: три варианта",
    "hb.h24.s4.b" to "Вы ведёте группу через старый лес. Впереди мокрый бревенчатый мост через быструю реку; очевидной альтернативы нет.\n\nДва обычных варианта — осторожно перейти или искать другой путь. Поиск нестандартного даёт третий: светит солнце, река быстрая, но, возможно, её можно перейти вброд; примерно в 100 м выше по течению, кажется, есть мост шире; у вас есть верёвка, значит сильный участник может закрепить конец на дереве на другом берегу и натянуть как перила; все снимают ботинки, подворачивают штаны, переходят, обедают на другом берегу и сушат носки.\n\nПравило: есть у вас пять секунд или пять часов, тратьте примерно половину времени на обычные варианты, а затем сознательно переходите к нестандартным. Реальный пример: плот набирает воду, около десяти секунд на откачку, посуды на борту нет — трое сняли по одному резиновому сапогу и вычерпали; лодка быстро стала сухой ценой двух холодных ног.",
    "hb.h24.s5.h" to "Взвешивание: вероятность x относительная важность",
    "hb.h24.s5.b" to "Сравнивать риск движения без тропы с выгодой моста — это сравнивать яблоки с апельсинами. Единственный рабочий способ — взвесить каждый риск и выгоду по двум осям:\n\n• Вероятность (P): насколько вероятно, достаточно шкалы от 1 (низкая) до 3 (высокая).\n• Относительная важность (RI): насколько это важно для вас, тоже от 1 до 3.\n\nВес = P x RI. Очень вероятный (3) и очень важный (3) риск даёт 9; маловероятный (1) и неважный (1) даёт 1.\n\nВ случае с мостом победил брод: у него были выгоды, которых не было у других (относительная безопасность, ощущение приключения), и хотя риск-пунктов больше, ни один не был серьёзным.\n\nПомните о субъективности: RI полностью зависит от ценностей, а группы различаются. Если команда говорит, что ни при каких условиях не хочет промокнуть, лучший вариант — обход; если время поджимает, мост может быть оптимальным.",
    "hb.h24.s6.h" to "Две проверки",
    "hb.h24.s6.b" to "Никогда не позволяйте системе решений решать за вас. Она интегрирует и взвешивает, но не становитесь жёсткими: если веса сильно неверны, вывод будет сильно неверным (мусор на входе — мусор на выходе).\n\nДве проверки:\n\n• Спросите, укладывается ли желаемое в здравый смысл. Любой может построить внутренне связное рассуждение на совершенно ложной предпосылке.\n• Оставьте место иррациональному сомнению — слушайте интуицию. Многое из того, что мы зовём интуицией, — долгий опыт, работающий ниже сознания: небо ещё синее, но вы чувствуете приближение непогоды; вы уверены, что над скалой есть проходимая щель. Пересекая трещиноватый ледник, почти каждый шаг — выбор влево или вправо, и опытные альпинисты часто не используют никаких явных признаков.\n\nИнтуицию нельзя выучить по книге, но можно тренировать: ведите её записи, следуете вы ей или нет — как часто она была права и как часто это была не интуиция, а усталость или страх.",
    "hb.h24.s7.h" to "Выполнить, затем скорректировать",
    "hb.h24.s7.b" to "Выполнение — последний шаг, как проводка клюшки через мяч в гольфе. Многие правильные решения не дают ничего, потому что их никогда ясно не сформулировали и не выполнили.\n\nЗатем подстраивайтесь под новую информацию. Условия меняются быстро: если канал оказался слишком глубоким для брода, это хорошая причина изменить план; но если река проходима, а один человек поскользнулся и все заколебались, нужна рука, а не отступление.\n\nХорошие руководители подстраиваются под новую информацию и мнения, но не поддаются давлению и не меняют суждение, чтобы понравиться или избежать конфликта.\n\nИ последнее: если вы сделали всё возможное, не сожалейте. Идеальных решений не бывает. На Аконкагуа, имея пять резервных дней на погоду, в один год три из них провели запертыми в палатке на 5 700 м; в 03:00 следующего утра казалось слишком плохо, чтобы пытаться, а в 07:00 погода была идеальной, и другая команда вышла на вершину. Остаётся только смеяться — и использовать и успехи, и провалы, чтобы улучшить следующее решение.",
    // ---------- h25 ----------
    "hb.h25.s1.h" to "Три уровня ответственности: действие, мысль, чувство",
    "hb.h25.s1.b" to "Традиционное определение касается только поведения: это можно, то нельзя. Этого мало.\n\nВы всегда влияете на окружающую среду: на природе, на работе, в сообществе, дома. Влияют не только поступки, но и мысли и чувства. Участник в плохом настроении, ругающий шнурок или потерянную карту, делает напряжённой всю команду; водитель автобуса с чувством юмора меняет настроение салона.\n\nВаша жизнь похожа на костюм. Руководители, которые думают, что можно работать на пределе всю неделю, а в отпуске полностью расслабиться, обманывают себя. Смотрите на каждый контекст как на пьесу, сценарий которой вы помогаете писать: если вы несёте злость после спора с начальником, лексика будет тяготеть к злости и раздражению, и сценарий пойдёт за ней.\n\nВнимание к деталям — часть ответственности: как вы отвечаете на звонок о записи, как представляете новичков, как исправляете ошибки и проверяете снаряжение, задаёт тон всей программе.",
    "hb.h25.s2.h" to "Контракт руководителя",
    "hb.h25.s2.b" to "Руководство похоже на контракт — без подписи, но реальный. Люди ждут, что вы поведёте, и взамен дают вам это право. Ключевые условия:\n\n• Держать группу в безопасности и целостности — без травм, происшествий и потерь, и это в основном зависит от вас.\n• Помочь группе достичь цели: вершины, переправы или хорошего дня в лесу.\n• Помочь участникам получить качественный опыт.\n• Вести в рамках закона.\n\nНа практике: заранее оценивайте погоду, снег и опасности реки; управляйте временем, чтобы избежать лишних холодных ночёвок; проявляйте настойчивость (обязанность не дать группе потеряться — ваша); имейте достаточно навыков и снаряжения для аварий; знайте состояние участников — Тим вымотан, у Клаудии хуже мозоли, любой из них может остановить последние километры; знайте, где каждый, с надёжными людьми на обоих концах группы.",
    "hb.h25.s3.h" to "Не злоупотребляйте ролью",
    "hb.h25.s3.b" to "Ответственность может ударить в голову. Без надзорных полномочий никогда не будьте грубы и не давите только потому, что вы руководитель; это равно относится и к неформальному руководству, например в поездке с друзьями, которые смотрят на вас как на гида.\n\nТоньше: не используйте авторитет, чтобы уйти от честного и внимательного разбора. Если вы приняли решение по маршруту, в котором не уверены, а участник возражает, не прячьтесь за званием; примите новую информацию и, если лучшее предложение вас убедит, измените линию.",
    "hb.h25.s4.h" to "Конфликт — это айсберг",
    "hb.h25.s4.b" to "Настоящая причина конфликта обычно не то, что видно. Любой конфликт — айсберг, в основном под водой: мелкая стычка недельной давности, неудача или что-то неприятное.\n\nЛюди, которые кажутся постоянно злыми, грубыми, давящими или враждебными, часто неуверенны в себе — неуверенность, которая может идти из детства.\n\nНикто не просит вас быть психотерапевтом на тропе, но игнорировать эти скрытые проблемы и связанные с ними эмоции наивно: они делают людей защищающимися, неразумными и конфликтными. Чем чувствительнее вы к скрытому, тем эффективнее справляетесь с конфликтом.",
    "hb.h25.s5.h" to "Разрешение конфликта: построить доверие",
    "hb.h25.s5.b" to "Ключ не в том, чтобы переспорить или победить другого, а в том, чтобы найти и построить доверие, чтобы оба стояли на одном месте и создали общее видение, где выигрывают все.\n\nСлучай на рафтинге: дни дождя подняли реку; впереди она делится, и левый рукав необычно быстрый даже без дождя. Вы считаете левый слишком опасным для новичков и выбираете правый. Все согласны, кроме Дэна и Норы, опытных не меньше вас: они считают правый скучным и начинают убеждать других собрать вторую группу на левый.\n\nКонкретные шаги:\n\n• Сначала управляйте собственной реакцией. Как бы грубо ни вели себя, реакцию контролируете вы; потеряете самообладание — отдадите им контроль.\n• Не навешивайте ярлыки слишком рано. Если вы сосредоточены на «Дэн жалуется», «Нора считает себя выше», вы создаёте самосбывающееся ожидание и снижаете шансы на успех.\n• Идите к проблеме: подойдите к человеку и сядьте с ним на привале вместо того, чтобы избегать.\n• Начинайте без угрозы, от общих интересов (работа, семья, спорт, прошлые походы).\n• Помните, что доверие растёт из заботы: слушайте по-настоящему, старайтесь увидеть с его стороны.\n• Делайте мелкие попутные одолжения: «Нора, помочь с ужином?» Одна бытовая фраза может стать самой важной за день.\n\nДоверие не обязано доходить до «крёстный моего единственного ребёнка». Достаточно: «Мы не согласны. Но я вижу, что вы искренни, хотите сделать правильно, и замечаю, что вы слушаете; я готов ответить тем же».",
    "hb.h25.s6.h" to "Обязанность ведомого",
    "hb.h25.s6.b" to "Даже обученных руководителей иногда ведут. Помните роль ведомого:\n\n• Дайте руководителю уважение, необходимое для работы, особенно менее опытному: ничто так не обескураживает нового руководителя, как человек с небольшим опытом, который весь день холоден, критичен или свысока.\n• Комментируйте решение руководителя только когда уверены, что это нужно, чтобы предотвратить худшее, и делайте это наедине, не при группе.\n• Поддерживайте позитивно: поднимайте настроение, помогайте участникам, показывайте пример, когда придёт ваш черёд.\n\nДаже если вы не хотите вести, не используйте это как повод не учиться и иногда не пробовать руководство. Вспомните курс сердечно-лёгочной реанимации: вы надеетесь никогда его не применить, но знание ценно; а понимание давления и ответственности ведущего делает вас лучшим ведомым.",
    // ---------- h26 ----------
    "hb.h26.s1.h" to "Компас и азимут",
    "hb.h26.s1.b" to "Совместите цель, отметку 0° и центр стрелки; когда компас лежит ровно и успокоился, азимут под северным концом стрелки — это азимут от вас к цели (если N показывает 36°, цель в 36° к востоку от севера).\n\nЧетыре правила:\n\n• держите компас как можно ровнее;\n• не подносите к магнитным предметам;\n• никогда не путайте южный конец с северным — это ошибка в 180°;\n• учитывайте местное магнитное склонение.",
    "hb.h26.s2.h" to "Метод часов",
    "hb.h26.s2.b" to "Правило: половина угла между часовой стрелкой и солнцем, а 12 указывают на север. Обычно быстро работает с 09:00 до 16:00.\n\nМетод: разделите текущее время пополам и направьте эту часовую отметку на солнце; тогда 12 показывают север. В 14:40 половина — 07:20; направьте 07:20 на солнце, и 12 дадут север.\n\nДва равносильных способа: держите часы плоско, часовой стрелкой на солнце, и продолжите назад биссектрису между стрелкой и 12 — это север; либо воткните палочку вертикально в центр плоского циферблата, поворачивайте часы, пока тень палочки не совпадёт с часовой стрелкой, и обратная биссектриса между стрелкой и 12 даст север.",
    "hb.h26.s3.h" to "Палка и тень",
    "hb.h26.s3.b" to "В солнечный день воткните палку в землю. Тень движется за солнцем и самая короткая в полдень; линия, соединяющая концы тени, прямая, а перпендикуляр к ней — линия север–юг.\n\nТочнее: начертите концентрические окружности через 1 см на листе 50 x 50 см, закрепите его ровно на доске и воткните вертикально иглу 12–15 см в центр. По мере движения солнца конец тени пересекает окружности; отметьте точки, соедините две точки на одной окружности, и середина укажет на центр — это и даёт линию север–юг.",
    "hb.h26.s4.h" to "Луна и звёзды",
    "hb.h26.s4.b" to "Луна: первая четверть — на востоке в 18:00, на западе в полночь; последняя четверть — на востоке в полночь, на юге в 06:00; полная — на востоке в 18:00, на юге в полночь, на западе в 06:00.\n\nПолярная звезда: строго на север, на высоте, равной вашей широте. Найдите её по Большой Медведице или Кассиопее: продлите две звезды ковша примерно на пять расстояний между ними; если ковш скрыт, отложите примерно две ширины «W» Кассиопеи за ней.\n\nЮжный Крест: виден ниже 23°30' с. ш. в некоторые ночи, четыре яркие звезды крестом; продлите длинную ось от верхней звезды через альфу примерно на 4,5 её длины (там нет звезды), чтобы найти юг.",
    "hb.h26.s5.h" to "Рельеф и растения",
    "hb.h26.s5.b" to "Некоторые признаки могут указывать направление:\n\n• одиночное растение обычно пышнее с солнечной стороны, а мох может быть на теневой северной стороне ствола;\n• в северном Китае годичные кольца часто шире с южной стороны.\n\nЭто даёт лишь грубое направление; проверяйте описанными способами и никогда не полагайтесь только на них.",
    "hb.h26.s6.h" to "Основы карты: широта, долгота и UTM",
    "hb.h26.s6.b" to "Земля делится на 360° и по направлению восток–запад, и по направлению север–юг. Долгота идёт по 180° в каждую сторону от Гринвича; широта — по 90° в каждую сторону от экватора; градус — это 60', минута — 60\".\n\nЛинии сетки на топографической карте перпендикулярны и равны по размеру, но Земля — эллипсоид, поэтому ячейки широты/долготы не должны быть равными. Причина в том, что сетка — это не широта/долгота, а UTM (Universal Transverse Mercator). Проекция изображает трёхмерную поверхность на плоскости; Меркатор предложил свою в XVI веке.\n\nПрежде чем читать карту, уточните проекцию и систему координат, иначе отсчёты по сетке не совпадут с координатами GPS.",
    "hb.h26.s7.h" to "Если вы заблудились",
    "hb.h26.s7.b" to "Заблудиться в горах очень опасно; выработайте привычку наблюдать маршрут. Без необходимости избегайте маркировки пути (флажки, туры) из экологических соображений.\n\nЕсли метить всё же нужно, три условия: позиция видна; направление однозначно, без двусмысленности; маловероятно, что метка скоро разрушится.\n\nЕсли заблудились, не паникуйте: сохраняйте спокойствие, экономите силы и используйте то, что вокруг:\n\n• поднимитесь на возвышенность, найдите ориентир — хребет или строение — и определите позицию;\n• в лесу обычно есть тропы, проложенные людьми; идя по ним, часто выходят к людям.",
    // ---------- h27 ----------
    "hb.h27.s1.h" to "Шесть принципов выбора места под лагерь",
    "hb.h27.s1.b" to "• Близко к воде: для лагеря нужна вода, поэтому стойте у ручья, озера или реки, но не ближе 60 м от источника. Это ограничивает загрязнение и безопаснее: реки под снежными вершинами обычно поднимаются к вечеру и гораздо сильнее в сезон дождей, поэтому не давайте воде дойти до палаток.\n\n• Защита от ветра: особенно на гребнях, перевалах и вершинах (или предвершинах). На северной стороне Эвереста около 7 500 м ветровая воронка может снести целый лагерь и разрушить усиленные палатки. Также ставьте входы палаток не по ветру.\n\n• Солнце или тень: в верхних лагерях обычно предпочитают солнце, но в жару, когда люди днём в палатке, подумайте о тени — температура в альпийской палатке на прямом солнце резко растёт.\n\n• На снегу или льду: насыпьте и утрамбуйте ровную площадку. При долгих стоянках снег под палаткой тает или проседает неравномерно; поднимите палатку и заполните углубления свежим снегом.\n\n• На осыпи: выберите самое ровное место, чтобы меньше работать, уберите крупные камни и заполните мелкими; при долгих стоянках заполните щели мелким песком.\n\n• Смотрите вверх и вниз: проверьте, нет ли сверху сухих деревьев и камнепада; не на гребне ли вы и не в открытой ли котловине (молнии); не в русле ли сезонного потока, в селевой промоине или в низине; не на краю ли обрыва; не может ли котловина затопиться; не в местах ли обитания крупных животных.",
    "hb.h27.s2.h" to "Мэйли Сюэшань, 1990: место лагеря, приведшее к катастрофе",
    "hb.h27.s2.b" to "В декабре 1990 года китайско-японская команда пыталась взойти на Мэйли Сюэшань (6 740 м). Крупнейшая в истории района альпинистская катастрофа унесла 17 жизней (11 японцев и 6 китайцев). Основной причиной стал лагерь: японская сторона настояла на том, чтобы поставить лагерь 3 под большим снежным склоном, и ночью огромная лавина засыпала весь лагерь. Никто не выжил.\n\nЭто урок, который надо помнить прежде всего при выборе верхнего лагеря: комфорт и удобство никогда не должны перевешивать оценку лавинных путей.",
    "hb.h27.s3.h" to "Зонирование и обустройство базового лагеря",
    "hb.h27.s3.b" to "Базовый лагерь большой команды похож на город: сначала планируют, затем строят по плану. Полный лагерь можно разделить на зоны сна, снаряжения, столовой, общения, совещаний, воды, энергоснабжения и санитарии, с поправкой на размер команды.\n\nРасположение:\n\n• Зона сна должна быть очень ровной для комфорта; не слишком близко к кухне (утренняя готовка мешает спать) и не рядом с зонами общения и совещаний.\n• Зона снаряжения под управлением назначенного человека, разумно близко к спальной.\n• Столовая может быть рядом или объединена с зонами общения и совещаний, но должна быть на расстоянии от спальной и от других команд.\n• Вода: разделите верхнюю и нижнюю точки — верхняя для готовки, нижняя для мытья.\n• Энергия — вдали от сна и разумно близко к кухне.\n• Санитария — с подветренной стороны и далеко от всего остального.\n\nОстальные зоны требуют меньше выравнивания; не уничтожайте растительность, чтобы выровнять зону общения. Ставьте палатки рядами, где возможно, растягивайте оттяжки вне троп, соединяйте палатки верёвками для лучшей ветроустойчивости. Закрепляйте переносными камнями, а не копайте лопатой и не вбивайте в грунт — это повреждает почву.",
    "hb.h27.s4.h" to "Сколько лагерей на маршруте и где",
    "hb.h27.s4.b" to "Число лагерей растёт с длиной маршрута и падает с квалификацией команды. На северной стороне Эвереста обычная команда ставит пять лагерей выше базового; команда тибетских гидов может обойтись тремя: базовый лагерь на 6 500 м, промежуточный базовый на 7 790 м, лагерь 2 на 8 300 м, лагерь 3, вершина и возврат в базовый.\n\nВыбирайте лагеря по двум принципам: безопасность и комфорт. На высоте нет растительности, поэтому забота об окружающей среде означает защиту скал и вынос мусора.\n\nСанитария должна быть в безопасном месте — не выбирайте опасное место только ради уединения; используйте стенку из снежных блоков или выкопанную яму. Лучше всего выносить отходы в специальном мешке. Всегда носите лопату для снежных лагерей, выравнивайте и утрамбовывайте площадку, чтобы избежать просадки.\n\nЕсли место не подходит для палаток и находится в опасной зоне, выберите незаметный участок, где можно поставить несколько независимых точек страховки. На сложном рельефе держите обвязку на себе постоянно, в том числе в туалете и во сне.",
    "hb.h27.s5.h" to "Семь принципов Leave No Trace",
    "hb.h27.s5.b" to "Альпийские экосистемы хрупки и восстанавливаются медленно. Американская концепция низкого воздействия — семь принципов LNT — широко применяется:\n\n1. Планируйте и готовьтесь: знайте местные правила и особые условия, готовьтесь к экстремальной погоде, опасностям и авариям; выбирайте время вне пиков посещения; ходите малыми группами, разбивая большие команды на группы по 4–6 человек.\n\n2. Ходите и ставьте лагерь на устойчивых поверхностях: оборудованные тропы, стоянки, скалы, галечник, сухая трава или снег. Используйте тропы там, где они есть, не срезайте углы и не прокладывайте новые линии, никогда не расчищайте путь, срубая деревья.\n\n3. Утилизируйте отходы правильно: выносите весь мусор, проверяйте лагерь и зону активности перед уходом, выносите гигиенические принадлежности, включая бумагу. Закапывайте человеческие отходы не ближе 60 м от воды; мойте не ближе 60 м, никогда у источника, небольшим количеством биоразлагаемого мыла, разбрасывая серую воду.\n\n4. Оставляйте то, что нашли: культурные и исторические объекты можно посещать, но не трогать; сохраняйте рельеф, растения и природные объекты; не вводите и не переносите чужеродные виды; не стройте сооружения и не копайте траншеи.\n\n5. Минимизируйте влияние костра: используйте портативную горелку, она воздействует меньше огня. Где огонь разрешён, используйте существующие кольца, держите костёр небольшим, собирайте сухие ветки, которые ломаются руками, никогда не рубите живые деревья и полностью тушите огонь и разбрасывайте золу перед уходом.\n\n6. Уважайте диких животных: наблюдайте издалека, не преследуйте и не приближайтесь; не кормите — кормление вредит здоровью, меняет поведение и привлекает хищников и другие опасности. Храните еду и мусор надёжно, избегайте чувствительных сезонов (гон, выведение потомства) и установленных мест и времени водопоя.\n\n7. Будьте внимательны к другим: уважайте другие команды, берегите их опыт, будьте вежливы и уступайте на тропе; при встрече с нагруженной группой отходите вниз по склону; ставьте лагерь и отдыхайте вдали от тропы и людей, не шумите.\n\nИ ещё одно: избегайте туров, флажков и краски для маркировки. Используйте компас или GPS — профессиональнее и интереснее.",
    "hb.h27.s6.h" to "Костры и местные обычаи",
    "hb.h27.s6.b" to "В принципе готовьте на газовой горелке. Если костёр необходим, используйте отведённое место либо галечник, песок или камень, а хворост собирайте рядом. В жаркую сухую погоду особенно остерегайтесь лесных пожаров.\n\nРядом с деревнями не мешайте жителям и не шумите. В районах этнических меньшинств особенно внимательно относитесь к местным обычаям и пищевым привычкам, поддерживайте добрые отношения: культурное разнообразие так же притягательно, как экологическое.",
    // ---------- h28 ----------
    "hb.h28.s1.h" to "Потеря ориентировки — одна из главных причин происшествий",
    "hb.h28.s1.b" to "Потеря ориентировки — важная причина происшествий на природе, и всё же многие любители уделяют ей мало внимания.\n\nВ природной среде, особенно незнакомой, вероятность высока. Частые ситуации:\n\n• густой кустарник или каменные россыпи — следы плохо видны, и вы сходите с маршрута незаметно;\n• дождь, туман или сумерки — плохая видимость ведёт к потере пути;\n• переправы, место, где открытый участок входит в густой лес, и разветвляющиеся в долине кулуары — ошибки концентрируются на переходах рельефа.",
    "hb.h28.s2.h" to "Как не заблудиться",
    "hb.h28.s2.b" to "• Изучите район заранее и выберите узнаваемые ориентиры (гребни, реки, боковые долины).\n• Идите по тропам и оборудованным маршрутам; не прокладывайте свою линию и не меняйте план под импульсом.\n• Умейте описать своё положение: выше или ниже, гребень или долина, сколько ручьёв пересекли, изменился ли рельеф и растительность.\n• В длинных экспедициях берите спутниковый телефон.\n• Оставьте карточку экстренного контакта, запомните номера экстренных служб и несите необходимое.",
    "hb.h28.s3.h" to "Принцип STOP",
    "hb.h28.s3.b" to "STOP означает Stay, Think, Observe, Plan (остановись, подумай, осмотрись, планируй).\n\n• Stay: если на природе что-то пошло не так, оставайтесь на месте; не действуйте наугад.\n• Think: успокойтесь и оцените ситуацию как можно объективнее и полнее.\n• Observe: посмотрите на участников, команду и обстановку, ищите возможные решения.\n• Plan: соедините факторы и спланируйте следующий шаг.\n\nЭто работает при потере ориентировки, травме, внезапной смене погоды и не только; это стандартная последовательность первой реакции.",
    "hb.h28.s4.h" to "Шесть правил при потере ориентировки",
    "hb.h28.s4.b" to "Сохраняйте спокойствие и сначала остановитесь / определите ориентиры / знайте, как звать помощь / ждите активно и экономите силы / подавайте сигналы, когда придёт помощь / действуйте методично.\n\nНочью разведите небольшой костёр для тепла. Спасатели редко приходят сразу, поэтому поспите немного, чтобы восстановиться. Поставьте обычный лагерь или аварийное укрытие. Уберите еду в мешок и держите подальше от места, где вы находитесь, чтобы запах не привлекал животных.\n\nЕсли слышите спасателей, многократно проводите фонарём по небу или включите красный сигнал на налобном фонаре, чтобы обозначить себя.",
    "hb.h28.s5.h" to "Как звать помощь",
    "hb.h28.s5.b" to "При наличии мобильной связи или рации свяжитесь с полицией (110), скорой (120) или местной спасательной группой — контакты групп есть на платформе происшествий Китайской ассоциации альпинизма (cmasports.cn).\n\nБез связи и рации отправьте кого-то за помощью, лучше двоих вместе.\n\nДавайте точную информацию: ваше положение либо рельеф, который вы прошли, и что видели — выше или ниже, гребень или долина, сколько ручьёв, изменился ли рельеф и растительность.\n\nПосыльные должны аккуратно помечать путь, чтобы спасатели могли идти по нему. Если вы переходите в более безопасное место, убедитесь, что спасатели всё равно смогут вас найти:\n\n• привяжите яркую ткань или снаряжение к ветвям либо положите на гребне;\n• услышав спасателей, свистите, стучите камнем, бейте в котелок или кричите.",
    "hb.h28.s6.h" to "Десять необходимых вещей",
    "hb.h28.s6.b" to "Список того, что носят всегда, должен включать минимум:\n\n• запасную одежду (ветрозащита, куртка или утеплитель)\n• защиту от дождя (чехол на рюкзак, дождевик или зонт)\n• нож (лёгкий, многофункциональный)\n• спички и зажигалку или ферроцериевое кресало (лучше два разных источника огня)\n• налобный фонарь или фонарик с запасными батареями\n• аптечку первой помощи\n• запас еды и воды\n• солнцезащиту и утепление\n• карту и компас (или GPS)\n• аварийное укрытие (например, спасательное одеяло)\n\nЕсли не хватает одного из пяти — воды, укрытия, тепла тела, воли к выживанию, еды, — вы или ваша команда уже в риске. Действуйте: пейте достаточно и разумно расходуйте еду (еда наименее срочна; с теплом, отдыхом и водой человек держится гораздо дольше); экономите силы и избегайте бессмысленных нагрузок; сохраняйте волю к выживанию и управляйте страхом и паникой.",
    "hb.h28.s7.h" to "Сохранять тепло в ожидании помощи",
    "hb.h28.s7.b" to "• Найдите или постройте укрытие от ветра и дождя; выберите место, безопасное от затопления и камнепада.\n• Изолируйтесь от холодной мокрой земли ковриком или растительностью.\n• Укройтесь сухой растительностью (папоротник, трава) для дополнительного тепла и изоляции.",
    // ---------- h29 ----------
    "hb.h29.s1.h" to "Обезвоживание: тихий двигатель плохих решений",
    "hb.h29.s1.b" to "Обезвоживание вызывает дискомфорт, снижает суждение и координацию, способствует высотной болезни, гипотермии и перегреву, а в тяжёлых случаях убивает.\n\nПри нормальной температуре тела человек без воды живёт всего 3–4 дня. Организм расходует около 2,5 л в сутки: с мочой (около 1 400 мл), дыханием (около 400 мл), потом (около 600 мл) и калом (около 100 мл), и это надо восполнять питьём и едой.\n\nОсновные симптомы: жажда, мало мочи, тёмная моча, морщинистая кожа, истощение, потеря аппетита.\n\nПрофилактика: подстраивайте питьё под потоотделение, принимая небольшие порции электролитного напитка до, во время и после нагрузки. Мнемоника: пей вовремя / добавь электролиты / малыми порциями часто / следи за скудной и тёмной мочой.",
    "hb.h29.s2.h" to "Четыре степени перегрева",
    "hb.h29.s2.b" to "Перегрев развивается: ощущение жара → тепловое истощение → тепловой удар → гипонатриемия.\n\nПричины: жара, неподходящая одежда, нехватка воды, переутомление, длительное воздействие, плохой сон.\n\n• Тепловое истощение: плохая концентрация, снижение внимания, замедленность, кожа слегка горячая, часто обильный пот.\n• Тепловой удар: температура выше переносимой органами, часто свыше 40,5 °C; угнетение сознания, спутанность или кома; кожа горячая, гиперемированная или бледная; судороги в тяжёлых случаях.\n• Гипонатриемия: избыточное питьё без выведения снижает концентрацию электролитов. Тошнота, головная боль, слабость, снижение сознания при почти нормальной температуре, судороги в тяжёлых случаях.\n\nОбратите внимание на ключевое отличие от теплового удара: при гипонатриемии температура почти нормальная. Значит, больше воды — не всегда лучше: остерегайтесь перепоя.",
    "hb.h29.s3.h" to "Четыре правила помощи при перегреве",
    "hb.h29.s3.b" to "Увести из жара и ослабить одежду / охлаждать распылённой водой / опрыскивать туловище / сочетать с потоком воздуха.\n\nПри жажде давайте пить, но следите за перепоем. Основной подход: переместить пострадавшего в тень, ослабить одежду и охлаждать туловище распылённой водой и потоком воздуха.",
    "hb.h29.s4.h" to "Профилактика перегрева",
    "hb.h29.s4.b" to "• Планируйте нагрузку разумно: выходите рано и избегайте полуденной жары; выспитесь заранее и не выходите в стрессе или в плохом настроении.\n• Охлаждайте голову и сбрасывайте тепло: носите подходящую одежду; на ходу смачивайте кепку, чтобы охладить голову; придя в тень, на минуту снимите кепку, чтобы сбросить тепло.\n• Отдыхайте в тени, вне прямого солнца и с хорошим движением воздуха; на привале снимайте рюкзак, кепку, расстёгивайте манжеты и ворот, подворачивайте штаны, чтобы быстро остыть.",
    "hb.h29.s5.h" to "Мозоли: профилактика и лечение",
    "hb.h29.s5.b" to "Причина: давление и трение между стопой и обувью, усиленные влагой и относительным теплом. Трение даёт мозоли на подошве или внешней стороне стопы; пот размягчает кожу и повышает трение, делая мозоли вероятнее. Это не ожоги, но более высокая температура кожи ускоряет их появление.\n\nПрофилактика: носки снижают мозоли; тальк, присыпка от потницы, антиперспирант или вазелин держат стопу сухой и уменьшают трение.\n\nЛечение:\n\n• продезинфицируйте иглу перед проколом (раскалите докрасна или протрите спиртовой салфеткой);\n• вскройте крупные мозоли или те, что вот-вот лопнут, чтобы выпустить жидкость;\n• сделайте кольцо из мягкой ткани вокруг мозоли, чтобы распределить давление и трение;\n• комбинированная антибактериальная мазь снижает риск инфекции; просто накройте пластырем или салфеткой, меняйте салфетку при намокании и держите участок вентилируемым.",
    "hb.h29.s6.h" to "Солнечные ожоги: лечение и профилактика",
    "hb.h29.s6.b" to "Избыток УФ расширяет капилляры под кожей, приливая больше крови к поверхности, поэтому кожа краснеет и нагревается.\n\nПрофилактика: наносите крем, подходящий погоде и высоте (обычно SPF выше 30); носите одежду с UV-защитой, шляпу, солнцезащитные очки и головной платок.\n\nЛечение:\n\n• обезболивание (например, аспирин) при покраснении и боли при лёгких и средних ожогах;\n• холодные компрессы или лёд, завёрнутый в ткань — никогда лёд прямо на кожу;\n• аккуратно промыть мягким мылом и нанести успокаивающий лосьон или гель алоэ;\n• припудрить тальком, чтобы уменьшить трение спальника или одежды ночью.\n\nКонтекст: на 6 500 м относительная влажность примерно в десять раз ниже, чем на уровне моря, поэтому потребность в жидкости гораздо выше; на 4 000 м интенсивность УФ в 2–3 раза выше, чем на уровне моря, а отражение от снега усиливает её ещё больше.",
    "hb.h29.s7.h" to "Обработка ожогов",
    "hb.h29.s7.b" to "Не вскрывайте пузыри без необходимости. Промойте рану чистой водой и накройте салфеткой с вазелином, чтобы повреждённая кожа не прилипала.",
    "hb.h29.s8.h" to "Небольшая аварийная аптечка",
    "hb.h29.s8.b" to "Для выходов дольше двух дней берите небольшую аптечку обычных аварийных средств:\n\n• Внутрь: средства от простуды, для желудка и кишечника, обезболивающие, антигистаминные, антибиотики (кожа, дыхательные пути, пищеварение) — конкретный совет спросите у врача.\n• Наружно: Юньнань Байяо, пластыри, бинты (рекомендуется гемостатический бинт), лейкопластырная лента, красный меркурохром, перекись водорода. Небольшой флакон бальзама и два флакона глазных капель (они же полезны для промывания ран) часто оказываются неожиданно удобными.",
    // ---------- h30 ----------
    "hb.h30.s1.h" to "Принцип 4-3-3: распределение ресурсов",
    "hb.h30.s1.b" to "Частые ошибки на природе: выпить всю дневную воду в жару; съесть завтрашнюю еду за один привал после долгого подъёма; выйти без физической базы.\n\nПринцип 4-3-3 распределяет запасы формы, еды и воды так:\n\n• 40 % расходуется на подъёме\n• 30 % расходуется на спуске\n• 30 % остаётся в резерве к концу активности\n\nОбщий резерв обычно покрывает форму, психическую энергию, еду, воду и запасные расходники вроде батареек.\n\nЕго ценность в том, что он разделяет «ещё двигаюсь» и «ещё есть запас»: вершина никогда не финиш; финиш — безопасное возвращение.",
    "hb.h30.s2.h" to "Правило трёх новых",
    "hb.h30.s2.b" to "Люди ищут более сильные впечатления, выбирая незнакомые места и маршруты. Но как руководитель или как участник проверяйте каждый выход правилом трёх новых до старта.\n\nТри новых вещи: новый маршрут, новые партнёры, новое снаряжение (или новая среда, новый сезон). Вместе они резко умножают неопределённость.\n\nПравило не запрещает выходить; оно требует, чтобы три вещи не совпадали одновременно — оставьте хотя бы одну знакомую.",
    "hb.h30.s3.h" to "Принцип STOP",
    "hb.h30.s3.b" to "Широко применяется в Китае и за рубежом, даёт эффективную реакцию, когда что-то пошло не так:\n\n• S = Stay: оставайтесь на месте; не действуйте наугад.\n• T = Think: успокойтесь и оцените точно.\n• O = Observe: осмотрите обстановку и найдите варианты.\n• P = Plan: соедините факторы и планируйте.\n\nПорядок: остановитесь там, где вы есть; спокойно подумайте и оцените как можно объективнее; осмотрите участников, команду и среду в поисках решений; затем соедините факторы и спланируйте следующий шаг.",
    "hb.h30.s4.h" to "Управление риском: последствие x вероятность",
    "hb.h30.s4.b" to "Риск — это вероятность происшествия, выраженная двумя мерами: последствием и вероятностью. Оценивайте каждую отдельно по категории риска, считайте значение риска и объединяйте их в общий уровень.\n\nШкала последствий (1–10 000, на примере травмы):\n\n• очень низкое: ссадина, ушиб, без времени восстановления\n• низкое: ушиб или растяжение, около недели\n• среднее: переливание или перелом, 1–6 недель\n• высокое: лечение в стационаре, больше 6 недель\n• очень высокое: стойкая инвалидность или смерть\n\nШкала вероятности (0,1–1,0):\n\n• редкая: раз в 10 лет или 1 из 10 выходов\n• маловероятная: раз в 5 лет или 1 из 5 выходов\n• возможная: раз в 3 года или 1 из 3 выходов\n• вероятная: раз в год или 2 из 3 выходов\n• почти неизбежная: несколько раз в год или почти каждый выход\n\nСочетание двух даёт наглядный уровень риска. Зона с очень высоким последствием и вероятностью, которую вы считаете очень низкой, требует наибольшей осторожности: привычные мысли «с нами этого не случится» и «мы не настолько невезучие» — это и есть оптимистическое искажение, за которым надо следить. Уделяйте этой зоне особое внимание и меры снижения.",
    "hb.h30.s5.h" to "Выявление рисков: перечислить опасности по одной",
    "hb.h30.s5.b" to "Выявление рисков означает найти каждую опасность и понять, где в альпинистской деятельности возможны травмы, финансовые потери, репутационный или рыночный ущерб. Травмы людей — приоритет.\n\nЧастые категории: скольжение и падения, падения с высоты; собственное состояние, знания и подготовка; проблемы акклиматизации; камнепад или сход льда от других групп; обрушение карнизов; лавины; высотная болезнь; отморожения; гипотермия; солнечные ожоги.\n\nМожно делать и по участкам. На маршруте Glacier 2 северной стены Юйчжу, например, перечислите риски каждого отрезка (Сидатань до BC, 20–40 минут на машине, 4 160–4 470 м; BC до точки смены ботинок, 2–3 часа, 4 470–4 670 м; смена ботинок до C1, 2–3 часа, 4 670–5 100 м; C1 до вершины 5 250 м, 40–90 минут, 5 100–5 250 м).\n\nПо участкам эффективнее общей оценки: абстрактное «есть риск» превращается в список, который можно проверить.",
    "hb.h30.s6.h" to "Три правила безопасного лагеря",
    "hb.h30.s6.b" to "Готовьтесь заранее / выбирайте место методично · предвидьте опасности / сосредоточьте защиту · оставайтесь бдительными · будьте готовы уйти в любой момент.\n\nПоследнюю фразу часто забывают: оценка риска не разовая. Погода, снег и состояние команды меняются, и нужно постоянно переоценивать, годится ли лагерь дальше.",
    // ---------- h31 ----------
    "hb.h31.s1.h" to "Три энергетических субстрата",
    "hb.h31.s1.b" to "Углеводы — важный структурный компонент клеток и основной энергетический субстрат. При умеренной аэробной работе организм работает в основном на углеводах; при анаэробной — почти исключительно на них. Они хранятся как глюкоза крови, мышечный гликоген и гликоген печени.\n\nЖиры: для многих спортсменов неэффективное топливо, но при длительной работе низкой интенсивности, включая альпинизм, больше энергии должно поступать из жиров, а не из углеводов. Это не делает запасы углеводов неважными: расщепление жиров зависит от постоянного притока гликогена и глюкозы крови. Если они подходят к истощению, жировой обмен резко замедляется.\n\nБелки: многие альпинисты упускают их как топливо. На самом деле достаточный белок лежит в основе силы и восстановления. Ориентир потребления — 0,8 г на кг в сутки, но тренирующимся и много ходящим в горах может требоваться существенно больше.",
    "hb.h31.s2.h" to "Тренировка повышает долю жиров",
    "hb.h31.s2.b" to "Аэробная работа ниже примерно 75 % пульса анаэробного порога улучшает жировой обмен. Хорошо подготовленные альпинисты могут получать 70–80 % энергии из жиров на длинных подъёмах.\n\nЭто важно на длинных маршрутах: с тем же запасом можно пройти дальше.\n\nНо следите за переключением: короткие взрывные усилия (быстрое прохождение крутого участка) возвращают питание к углеводам. Подготовленные переключаются быстро. Если гликоген истощается вскоре после старта, будьте особенно осторожны: мышечный гликоген не восстанавливается во время работы. Для лазания гликоген нужен и для взрывного усилия, и для поддержки жирового обмена, поэтому задавайте темп разумно.",
    "hb.h31.s3.h" to "Аминокислоты с разветвлённой цепью и аммиак",
    "hb.h31.s3.b" to "Аминокислоты с разветвлённой цепью (лейцин, изолейцин, валин) составляют около 20 % мышечного белка и необходимы для выносливости и мощности.\n\nКогда их уровень в крови падает ниже порога, организм расщепляет мышечный белок для восполнения — начинает есть собственные мышцы.\n\nЛюбой дефицит глюкозы и жирных кислот запускает это расщепление; в некоторых ситуациях катаболизм белка становится основным источником энергии. Он разрушает структуру мышечного белка и даёт много аммиака, токсичного для клеток. Высокий аммиак снижает работоспособность и мышление — особенно опасно на высоте, где решения принимаются постоянно.\n\nЗамечали запах аммиака после тяжёлого дня в горах? Это побочный продукт сжигания мышечного белка.",
    "hb.h31.s4.h" to "Стратегия питания на подъёме",
    "hb.h31.s4.b" to "Длинные альпийские подъёмы требуют полной пищевой стратегии. Два ключевых правила:\n\n1. Держите интенсивность в диапазоне, где работает жировой обмен, чтобы максимально сберечь гликоген.\n2. Следите за конкретными нутриентами:\n\n• достаточно углеводов, чтобы поддерживать глюкозу крови;\n• достаточно аминокислот с разветвлённой цепью, чтобы ограничить распад мышц;\n• вещества, нейтрализующие аммиак, чтобы белковый обмен не снижал работоспособность;\n• антиоксиданты (витамин C, витамин E) во время подъёма и на отдыхе.\n\nБелок: животные и растительные источники работают, но молочные продукты и яйца усваиваются эффективнее растительного белка, поэтому их нужно меньше. Избыток белка не улучшает результат: организм знает, что ему нужно, а остальное превращает или выводит.",
    "hb.h31.s5.h" to "Питание на маршруте: батончики и гели",
    "hb.h31.s5.b" to "Ранние альпинисты использовали энергетические батончики (Snickers, PowerBar) как еду на маршруте. Они энергоёмки, но требуют минимум поллитра воды сразу после для нормального усвоения; а переваривание батончика усиливает кровоток к кишечнику, что может ухудшить работоспособность.\n\nГели (например, GU, около 25 г углеводов на пакетик) проще использовать и усваивать: несколько глотков воды с гелем доводят концентрацию углеводов до 4–8 %, при которой желудок опорожняется быстрее всего.\n\nВ гелях есть также лейцин и валин — обе аминокислоты с разветвлённой цепью нужны для работы и восстановления, — плюс немного кофеина, который поддерживает жировой обмен и бодрость.\n\nПримечание: кофеин сужает сосуды; применяйте осторожно и индивидуально.",
    "hb.h31.s6.h" to "Особые требования на высоте",
    "hb.h31.s6.b" to "Набор высоты меняет питание через две переменные:\n\n• Ниже влажность: на 6 500 м относительная влажность примерно в десять раз ниже, чем на уровне моря, поэтому неощутимые потери через дыхание и кожу резко растут, и пить надо больше.\n• Ниже аппетит: на высоте аппетит обычно падает, а расход энергии растёт.\n\nПоэтому правило на высоте: малыми порциями часто, преимущественно жидкое или полужидкое, и не ждите голода. Относитесь к еде как к запланированной задаче, а не как к тому, что делают по просьбе организма.",
    "hb.h32.title" to "Лавинное засыпание: выживание, реанимация и дыхательные пути",
    "hb.h32.summary" to "Главная причина смерти при лавине — асфиксия, а не холод. Время под снегом определяет, по каким правилам проводить реанимацию: в редакции 2023 года линия решения сдвинута с 35 на 60 минут, а температура ядра стала параллельным критерием.",
    "hb.h32.s1.h" to "Сначала цифры (вместе с методикой)",
    "hb.h32.s1.b" to "Выживаемость при критическом засыпании около 48 %, при полном засыпании 47,6 % (сводные данные редакции 2013 года), при частичном 96 %. Через 15 минут под снегом выживает около 93 %, через 18 минут около 91 %, через 35 минут 28–34 %. Структура причин смерти: асфиксия 65–100 %, травма 5–29 %, гипотермия 0–4 %. При цитировании год и методику указывают вместе, иначе у читателя возникает ощущение, что «цифры поменялись».",
    "hb.h32.s2.h" to "Четыре фазы кривой выживаемости",
    "hb.h32.s2.b" to "Фаза выживания (примерно первые 18 минут): смерть чаще от травмы, дыхательные пути обычно проходимы, главное — скорость. Фаза асфиксии (18–35 минут): рот и нос забиты снегом или кислород в воздушном кармане исчерпан, кривая падает круто — отсюда и «золотые 18 минут». Латентная фаза (35–90 минут): при наличии воздушного кармана и проходимых дыхательных путях включается защита холодом, кривая выполаживается. Фаза длительного пребывания (свыше 90 минут): преобладает гипотермия, изредка встречаются очень долгие выживания, и всё зависит от состояния дыхательных путей и скорости охлаждения.",
    "hb.h32.s3.h" to "Линия решения: с 35 на 60 минут",
    "hb.h32.s3.b" to "В редакции ICAR MedCom 2013 года разделительной линией были 35 минут; в редакции 2023 года — 60 минут, плюс температура ядра. Причин три: при пересмотре случаев зафиксированы восстановления спонтанного кровообращения при асфиксической остановке в пределах 60 минут; гипотермическая остановка может длиться дольше; линия на 35 минутах отсекает тех, у кого ещё оставался шанс. В обучении обе редакции дают рядом, а акцент делают на том, почему правило изменилось.",
    "hb.h32.s4.h" to "Порядок действий на месте",
    "hb.h32.s4.b" to "0–2 минуты: убедиться в отсутствии риска повторной лавины и камнепада, назначить наблюдателя, записать время схода или последнее известное время, определить последнюю точку, где человека видели, вызвать спасателей. 2–10 минут: поиск бипером, зондирование, начало раскопок — цель этого этапа «добраться до человека», а не «выкопать полностью». При достижении лица: сначала очистить рот и нос от снега и ледяной крошки, в течение минуты оценить признаки жизни, при отсутствии дыхания немедленно начать спасательное дыхание. При отсутствии признаков жизни: сортировка по правилу 60 минут. После извлечения: защита позвоночника, общее согревание, непрерывное наблюдение и как можно более быстрая эвакуация.",
    "hb.h32.s5.h" to "Приоритет дыхательных путей",
    "hb.h32.s5.b" to "У «сначала очистить дыхательные пути» есть конкретное содержание.\n\n1. Обструкция — это когда рот и нос полностью забиты плотным снегом или крошкой, а не «немного снега во рту». При сомнении считают, что пути проходимы.\n2. Наличие воздушного кармана не меняет действий: он влияет на вероятность, а не на решение.\n3. Спасательное дыхание начинают как можно раньше: при засыпании до 60 минут дыхание дают независимо от проходимости путей.\n4. Непрямой массаж сердца не обязательно ждать полной раскопки, его можно проводить и при изменённом положении тела.\n5. Не тянут человека за плечи, как только до него добрались: сначала очищают лицо и дыхательные пути, проверяют положение головы и шеи.",
    "hb.h32.s6.h" to "Гипотермия, травма и типичные ошибки",
    "hb.h32.s6.b" to "Триада при лавине — гипоксия, гиперкапния и гипотермия, порядок действий: сначала вентиляция, затем согревание. При гипотермической остановке действуют «мягко»: переносят в горизонтальном положении, полностью изолируют от холода, непрерывно наблюдают и доставляют в клинику, где есть экстракорпоральное согревание. На крутых склонах и в лесных лавинах доля травм заметно выше, и защитой позвоночника пренебрегать нельзя.\n\nТипичные ошибки: по-прежнему использовать 35 минут; решать, реанимировать ли, по глубине засыпания или наличию воздушного кармана; сначала тянуть тело, а потом очищать дыхательные пути; ждать полной раскопки, чтобы начать вентиляцию; не записывать время под снегом; принимать 25 % на 45-й минуте за подъём кривой.",
    "hb.h33.title" to "Комплект из трёх предметов: поиск, зондирование и раскопки",
    "hb.h33.summary" to "Смысл комплекта в том, чтобы уложить «найти» и «выкопать» в 18 минут. Поиск идёт в четыре этапа, их нельзя пропускать; скорость раскопок зависит от точки начала, уклона канала и смены работающих.",
    "hb.h33.s1.h" to "Рамка из четырёх этапов",
    "hb.h33.s1.b" to "В рекомендациях лавинного комитета ICAR, обновлённых в 2025 году, поиск делится на четыре этапа: поиск сигнала и подсказок (найти первый сигнал) → грубый поиск (сократить расстояние до 3–5 метров) → точный поиск (найти ближайшую точку на поверхности) → точечное зондирование (подтвердить место и глубину). Четыре этапа — это сжатие «от площади к точке»; пропуск этапа — самая частая потеря времени: тот, кто падает на снег и начинает точный поиск по первому сигналу, теряет десятки метров.",
    "hb.h33.s2.h" to "Бипер: ширина полосы прежде всего",
    "hb.h33.s2.b" to "Интервал между полосами поиска около 40 метров, от края отложений около 20 метров. Если нет уверенности, что полосу прочешете полностью, сокращают до 30 метров: лучше уже, чем шире. Сначала смотрят на поверхностные подсказки (перчатка, кончик палки, шлем, лямка рюкзака), а не опускают голову к биперу сразу. Вся группа переходит в режим приёма, телефоны и экшн-камеры выключают. При нескольких засыпанных первый сигнал помечают или подавляют и ищут следующий. На грубом поиске расстояние считывают до 3–5 метров: если число растёт, направление выбрано неверно, нужно вернуться тем же путём.",
    "hb.h33.s3.h" to "Точный поиск и зонд",
    "hb.h33.s3.b" to "На точном поиске бипер ведут по снегу крест-накрест, находят точку с минимальным показанием и помечают её — она определяет, какую площадь нужно прощупать зондом. Точечное зондирование: начинают от точки минимального показания, зонд держат под 90 градусов к поверхности снега (не к горизонтали), при отсутствии попадания расширяют поиск сеткой 25 на 25 сантиметров. Попадание в твёрдый предмет не означает попадания в человека: ищут сопротивление «мягкое, упругое, похожее на тело». Найдя, зонд оставляют в снегу — это центр будущих раскопок. Если глубина больше длины зонда, сначала снимают около метра снега и определяются заново.",
    "hb.h33.s4.h" to "Два случая разного угла зонда",
    "hb.h33.s4.b" to "Точечное зондирование при спасении партнёрами: зонд под 90 градусов к поверхности снега, иначе показание завышается углом склона. Зондирование на организованной линии: зонд держат вертикально (к горизонтали), чтобы показания глубины у разных участников были сопоставимы. Эти две формулировки нужно давать раздельно, иначе их легко перепутать. Личный зонд обычно 240–320 сантиметров, спасательным группам рекомендуют не меньше 3 метров и соответствие UIAA 157.",
    "hb.h33.s5.h" to "Точка начала раскопок: правило и обновление исследований",
    "hb.h33.s5.b" to "Традиционное правило: «от зонда вниз по склону отступить примерно на 1,5 глубины засыпания, подходить с низовой стороны и копать наклонный канал шириной 1–2 метра». Его всё ещё можно преподавать, но нужно говорить, что это эмпирическое правило. Упрощённая версия Avalanche.org: при глубине меньше метра отступить на шаг, при большей — на два. Исследование снежного конвейера на ISSW 2023 утверждает: если людей больше трёх и места хватает, копают прямо от зонда вниз по линии падения, так быстрее добираются до головы; смещаться стоит только при очень малой глубине или нехватке рук. Порядок обучения: принцип (всегда с низовой стороны) → правило → обновление исследований.",
    "hb.h33.s6.h" to "Снежный конвейер",
    "hb.h33.s6.b" to "Канал прокладывают по линии падения, шириной 1–2 метра, с уклоном, при котором снег уходит вниз сам; критический уклон около 26 градусов, ниже него блоки скатываются обратно к зонду. Копающие встают в цепочку и передают снег в стороны или вниз; по эффективности приёмы располагаются так: сгребание быстрее всего, зачерпывание медленнее, нарезание блоков медленнее всего (только для плотного снега). Одного человека назначают руководителем раскопок: он следит за направлением, за состоянием снега выше и за положением засыпанного. Смена работает быстрее, чем упорство на пределе. Данные исследований: плотный снег около 13,2 сантиметра в минуту, мягкий около 25,3.",
    "hb.h33.s7.h" to "Достижение лица и распределение сил",
    "hb.h33.s7.b" to "Когда дошли до головы, порядок меняется: сначала очищают рот и нос и проверяют дыхательные пути, затем грудь и руки, чтобы грудная клетка могла расправляться, и только потом ноги и остальное тело. Не хватают за плечи и не тянут наружу, особенно за голову и шею. Ориентиры по времени: при спасении партнёрами коснуться человека за 10 минут и выкопать за 18.\n\nГруппа из трёх: один ищет и зондирует, двое копают; после попадания зондом ищущий переходит в руководителя раскопок или встаёт в смену. Группа из двух: один зондирует, второй копает, после попадания работают по очереди. Большая группа: назначают наблюдателя и регистратора, и не все бросаются в одну точку.",
    "hb.h34.title" to "Перила: точки страховки, прохождение узлов и перестёжка",
    "hb.h34.summary" to "Перила — это не «пристегнулся и в безопасности», а цепочка правильных подключений, которые человек делает сам, раз за разом. Три типа перил соответствуют трём наборам стандартов; в прохождении узлов и перестёжке главное — «сначала новое подключение, потом снятие старого».",
    "hb.h34.s1.h" to "Сначала разделить три типа перил",
    "hb.h34.s1.b" to "Перила-поручень: короткий участок с выходом на открытое место, крепят стропой, карабином с муфтой и восьмёркой, при сомнительной точке добавляют дублирование, двойная восьмёрка позволяет подключить две-три точки одновременно. Короткий участок фиксированной верёвки: крутой склон или один верёвочный участок, по которому ходят вверх-вниз, используют статическую или малодеформирующуюся верёвку, надёжные точки сверху и снизу, на конце верёвки — контрольный узел. Экспедиционное провешивание: длинный маршрут, много участков, работа с грузом, использование весь сезон, промежуточные точки через re-belay, статическая верёвка, остаток верёвки в мешке, регулярная проверка износа.",
    "hb.h34.s2.h" to "Материалы и стандарты",
    "hb.h34.s2.b" to "Динамическая верёвка EN 892 / UIAA 101 — для лидирования и срывов; для перил берут статическую EN 1891 A / UIAA 110: малое удлинение, стойкость к истиранию. Зажим EN 567, спусковое устройство EN 15151-1/-2, обвязка EN 12277, снаряжение для точек EN 795 / EN 959. Для провешивания обычно берут статическую верёвку 9–11 миллиметров: слишком тонкая быстро истирается, слишком толстая тяжела. Номер стандарта — основание и для закупки, и для проверки, и подсказка о том, под какую нагрузку предмет изначально проектировали.",
    "hb.h34.s3.h" to "Пять проверок точки страховки",
    "hb.h34.s3.b" to "Независимость: две точки должны быть на разных скальных массивах, разных деревьях, разных шлямбурах, а не две закладки в одной трещине. Уравнивание: нагрузку распределяют стропой или петлёй, угол делают как можно меньше. Направление: точка должна держать реальное направление нагрузки, а не только вниз — при провешивании маятник даёт боковую составляющую. Дублирование: кроме основной точки нужна независимая резервная, не разделяющая источник отказа. Острые кромки: на перегибе ставят протектор или удлиняют цепью.\n\nЧастая ошибка — «две точки, соединённые одной стропой в линию»: это не резервирование, а последовательный отказ.",
    "hb.h34.s4.h" to "Работа на провешивании",
    "hb.h34.s4.b" to "На этапе планирования определяют начало и конец каждого участка, промежуточные точки и точки отхода, оценивают длину верёвки (с запасом на узлы и подключения, лучше длиннее, чем короче), оценивают риск камнепада, лавин и грозы и выбирают способ крепления.\n\nНа этапе работы: в любой момент не менее двух подключений (единственное исключение — ввязывание в верёвку при лидировании); на конце верёвки контрольный узел; две верёвки соединяют двойным рыбацким узлом и заранее продумывают прохождение узла; на промежуточной точке верёвка идёт свободно; остаток верёвки в мешке; записывают длину каждого участка, положение точек, состояние верёвки и дату проверки. Пока провешивающий работает выше, под ним стоять нельзя.",
    "hb.h34.s5.h" to "Подъём и прохождение узла",
    "hb.h34.s5.b" to "Комплект для подъёма: жумар, грудной зажим (или второй схватывающий узел), петля для ноги, дублирующий схватывающий узел, PAS или стропа, каска. Движение — «встал, сел, подтянул», центр тяжести у верёвки. Принцип — два подключения, исключение только одно: ввязывание в верёвку при лидировании.\n\nПорядок прохождения узла (сначала новое, потом снятие старого): замедлиться и посмотреть → подключиться на PAS или стропу выше узла либо к близлежащей точке → поставить выше второй зажим и перенести на него вес → снять нижний зажим и поставить его выше узла → убедиться, что новое подключение держит, и снять PAS. Оба зажима одновременно без верёвки оставлять нельзя.",
    "hb.h34.s6.h" to "Перестёжка в двух направлениях",
    "hb.h34.s6.b" to "С подъёма на спуск: подключиться к точке → поставить спусковое устройство и правильно заправить верёвку → нагрузить устройство и проверить → снять жумар (оставив грудной зажим или дублирующий схватывающий узел) → снять второй зажим → убедиться, что спусковое устройство и дублирование работают, и снять PAS.\n\nСо спуска на подъём: поставить схватывающий узел или зажим выше спускового устройства → встать и перенести вес → поставить второй зажим и убедиться, что он держит → снять спусковое устройство. Перестёжка — самый аварийный этап, потому что переход идёт между «снятием старой системы» и «созданием новой».",
    "hb.h34.s7.h" to "Спуск и контрольный список",
    "hb.h34.s7.b" to "Спуск: выше спускового устройства ставят дублирующий схватывающий узел (прусик или автоблок) и подключают к ножной или поясной петле обвязки; на конце верёвки контрольный узел; сначала тест, потом снятие страховки; идут равномерно, не прыгая; при прохождении узла снаряжение переносят через PAS в два приёма. Если верёвка заклинилась, не встают под неё и не дёргают изо всех сил: сначала меняют угол или тянут сбоку.\n\nПроверка ABCDE перед выходом на верёвку: A — точки (независимость, уравнивание, направление, дублирование, острые кромки), B — дублирование (PAS и резерв снаряжения), C — подключения (муфты, узлы, контрольный узел), D — направление (ход свободный, верёвка не давит на скалу), E — выход (точки отхода, длина верёвки, связь).",
    "hb.h35.title" to "Переправа через реку: пороги, построение и действия при падении",
    "hb.h35.summary" to "Риск переправы определяется не «глубиной», а «глубиной, умноженной на скорость»; не тем, «умеете ли вы плавать», а тем, «сможете ли не встать после падения».",
    "hb.h35.s1.h" to "Жёсткие пороги",
    "hb.h35.s1.b" to "Глубина (в метрах), умноженная на скорость (в метрах в секунду), больше 1,0 считается непригодной для перехода вброд (верхний предел новозеландского руководства по безопасности на воде). Это условие для здоровых взрослых, без тяжёлого груза, на коротком отрезке; при большом рюкзаке, температуре воды около нуля и новичках в группе порог снижают, группа может принять внутренний предел 0,8. Скорость выше скорости шага уже потенциально опасна (проверяют, бросив ветку и пройдя вдоль берега). Если глубина выше бедра самого низкого участника группы — переправу пересматривают или ищут другое место. Подъём уровня на 15 сантиметров уже делает прежнее безопасное место опасным. Если дна не видно и вода мутная — не идут.",
    "hb.h35.s2.h" to "Выбор места",
    "hb.h35.s2.b" to "Первый вопрос всегда «обязательно ли мне переходить» — можно ли обойти, найти мост, подождать спада воды; этот вопрос снимает большую часть риска. Обычно проходимо: глубина до колена, дно — ровная галька; глубина до пояса, но течение очень медленное и дно ровное. Не переходят: на внешней стороне излучины (там глубже и быстрее), выше водопада, порогов, завалов и обрывов, на илистом и песчаном дне, сразу после сильного дождя выше по течению или при подъёме воды. Смотрят и на зону выноса: куда унесёт человека, если он оступится. Ледниковое питание даёт минимум утром и максимум после полудня, переправу планируют на первую половину дня.",
    "hb.h35.s3.h" to "Рюкзак и одежда",
    "hb.h35.s3.b" to "Грудную стяжку расстёгивают обязательно, здесь нет разногласий: с застёгнутой стяжкой при падении рюкзак тянет плечи вперёд, и выбраться трудно. Плечевые лямки ослабляют, но не обязательно расстёгивают полностью. Поясной ремень — точка расхождения: американская школа предлагает расстёгивать, чтобы легче бросить рюкзак, новозеландский MSC предлагает застёгивать и использовать рюкзак как плавучесть (расстёгивают только грудную стяжку, ослабляют лямки и отрабатывают быстрое расстёгивание пояса). Оба подхода имеют свои условия, главное — единый порядок в группе и отработка: недопустимо, когда половина застёгнута, а половина расстёгнута.\n\nКроме того: переходят в обуви, чтобы защитить стопы; внешние крепления подтягивают; электронику и лекарства кладут в гермомешок и держат у тела; палки без колец ставят с наветренной, то есть верховой, стороны; после переправы быстро переодеваются в сухое и пьют горячее.",
    "hb.h35.s4.h" to "Три варианта построения",
    "hb.h35.s4.b" to "Треугольник (три человека): лицом внутрь, держатся за плечи или рюкзаки, за один приём двигает ногу только один человек, сильнейший стоит с верховой стороны, командует тоже он. Шеренга с взаимной поддержкой (от трёх человек): сильнейшие по краям, руку проводят между рюкзаком и спиной соседа и берутся за его пояс или лямку с дальней стороны, идут боком, приставными шагами, новички в середине. Один: опираются прочной палкой или шестом с верховой стороны, получая три точки опоры, идут лицом к течению боком, мелкими приставными шагами, наискось вниз по течению; при воде выше колена и быстром течении в одиночку не идут. Команда единая: «шаг, стоп, шаг».",
    "hb.h35.s5.h" to "После падения",
    "hb.h35.s5.b" to "Первое правило: не вставать. Нога может застрять в расщелине камней или в завале, вода прижимает человека вниз, голова оказывается под водой — это заклинивание стопы, самый типичный механизм гибели при переправе.\n\nПравильное положение: на спине лицом вверх, ноги вниз по течению и у поверхности, голова поднята, руки разведены и работают как вёсла, направление держат наискось к берегу в технике обратной переправы; от препятствий отталкиваются ногами, а не пытаются встать на дно. Рюкзак в этот момент работает как плавучесть: с застёгнутым поясом он держит, с расстёгнутым — прижимают лямки руками. Если рюкзак зацепился, поднимают руки и выскальзывают из лямок, рюкзак лучше бросить. Перед выходом на берег сначала расстёгивают пояс, потом снимают лямку с верховой стороны.",
    "hb.h35.s6.h" to "Верёвка и тренировка",
    "hb.h35.s6.b" to "Использовать верёвку для помощи при переправе опасно, большинство групп недостаточно натренировано: верёвка запутывает плывущего, прижимает его под воду и затягивает страхующего с берега в реку. Если без верёвки не обойтись: верёвку закрепляют на берегу и никогда не привязывают к человеку; проходят с низовой стороны верёвки; заранее продумывают выдачу и освобождение верёвки и назначают страхующего на берегу; нельзя натягивать верёвку прямой линией поперёк быстрого потока.\n\nПорядок обучения: сначала на суше построение, хваты и команды, затем медленная вода по колено; отдельно отрабатывают «не вставать после падения» и сброс рюкзака за три секунды. Критерии: место выбрано с обоснованием за 5 минут, построение готово за 2 минуты, после падения правильное положение занято за 10 секунд.",
)
